# Minimal FTXUI layout simulator (x dimension only, plus y where needed)
class Req:
    def __init__(s, mx=0, my=0, gx=0, gy=0, sx=0, sy=0): s.mx,s.my,s.gx,s.gy,s.sx,s.sy=mx,my,gx,gy,sx,sy
def compute(elems, target):
    # elems: list of (min, grow, shrink) -> sizes
    size=sum(e[0] for e in elems); gsum=sum(e[1] for e in elems)
    ssum=sum(e[0]*e[2] for e in elems); ssize=sum(e[0] for e in elems if e[2]!=0)
    extra=target-size; out=[]
    if extra>=0:
        for m,g,s in elems:
            a=extra*g//max(gsum,1) if gsum else 0
            # C++ truncation toward zero; extra>=0 so fine
            extra-=a; gsum-=g; out.append(m+a)
    elif ssize+extra>=0:
        for m,g,s in elems:
            num=extra*m*s; den=max(ssum,1)
            a=-((-num)//den) if num<0 else num//den  # trunc toward zero
            extra-=a; ssum-=s*m; out.append(m+a)
    else:
        extra+=ssize; size-=ssize
        for m,g,s in elems:
            if s!=0: out.append(0); continue
            num=extra*m; den=max(size,1)
            a=-((-num)//den) if num<0 else num//den
            extra-=a; size-=m; out.append(m+a)
    return out

class Node:
    def __init__(s, kind, children=None, **kw):
        s.kind=kind; s.children=children or []; s.kw=kw; s.req=Req(); s.box=None
    def creq(s):
        for c in s.children: c.creq()
