// xterm 256 color palette RGB values
void Palette256RGB(int i, int* r, int* g, int* b) {
  static const int base[16][3] = {
      {0, 0, 0}, {128, 0, 0}, {0, 128, 0}, {128, 128, 0}, {0, 0, 128}, {128, 0, 128}, {0, 128, 128}, {192, 192, 192},
      {128, 128, 128}, {255, 0, 0}, {0, 255, 0}, {255, 255, 0}, {0, 0, 255}, {255, 0, 255}, {0, 255, 255}, {255, 255, 255}};
  if (i < 16) { *r = base[i][0]; *g = base[i][1]; *b = base[i][2]; return; }
  if (i < 232) {
    int k = i - 16;
    static const int lv[6] = {0, 95, 135, 175, 215, 255};
    *r = lv[k / 36]; *g = lv[(k / 6) % 6]; *b = lv[k % 6];
    return;
  }
  int v = 8 + (i - 232) * 10;
  *r = *g = *b = v;
}

// Mapping from the 256 color palette to the closest 16 color palette entry.
