    7,  7,  15, 15};

}  // namespace

Color::Support Color::TerminalSupport() {
  static Support support = [] {
    const char* ct = std::getenv("COLORTERM");
    std::string colorterm = ct ? ct : "";
    if (colorterm.find("24bit") != std::string::npos || colorterm.find("truecolor") != std::string::npos)
      return Support::TrueColor;
    const char* t = std::getenv("TERM");
    std::string term = t ? t : "";
    if (colorterm.find("256") != std::string::npos || term.find("256") != std::string::npos)
      return Support::Palette256;
    return Support::Palette16;
  }();
  return support;
}

Color Color::Palette16(int index) {
  Color c;
  c.type_ = Type::Palette16;
  c.r_ = static_cast<uint8_t>(index & 15);
  return c;
}

Color Color::Palette256(int index) {
  index &= 255;
  if (TerminalSupport() == Support::Palette16) return Palette16(kPalette256To16[index]);
  Color c;
  c.type_ = Type::Palette256;
  c.r_ = static_cast<uint8_t>(index);
  return c;
}

Color Color::RGB(int r, int g, int b) {
  if (TerminalSupport() == Support::TrueColor) {
    Color c;
    c.type_ = Type::TrueColor;
    c.r_ = r; c.g_ = g; c.b_ = b;
    return c;
  }
  int best = 16;
  long best_dist = 1L << 40;
  for (int i = 16; i < 256; ++i) {
    int pr, pg, pb;
    Palette256RGB(i, &pr, &pg, &pb);
    long dr = pr - r, dg = pg - g, db = pb - b;
    long dist = dr * dr + dg * dg + db * db;
    if (dist < best_dist) { best_dist = dist; best = i; }
  }
  return Palette256(best);
}

bool Color::FromName(const std::string& name_in, Color* out) {
  std::string name;
  for (char ch : name_in) name += static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
  static const std::map<std::string, int> names = {
      {"black", 0},      {"red", 1},          {"green", 2},        {"yellow", 3},      {"blue", 4},
      {"magenta", 5},    {"cyan", 6},         {"graylight", 7},    {"gray_light", 7},  {"white", 15},
      {"graydark", 8},   {"gray_dark", 8},    {"redlight", 9},     {"red_light", 9},   {"greenlight", 10},
      {"green_light", 10}, {"yellowlight", 11}, {"yellow_light", 11}, {"bluelight", 12}, {"blue_light", 12},
      {"magentalight", 13}, {"magenta_light", 13}, {"cyanlight", 14}, {"cyan_light", 14},
      {"brightblack", 8}, {"brightred", 9},   {"brightgreen", 10}, {"brightyellow", 11}, {"brightblue", 12},
      {"brightmagenta", 13}, {"brightcyan", 14}, {"brightwhite", 15}, {"grey", 7}, {"gray", 7}, {"grey_light", 7},
      {"grey_dark", 8}, {"greylight", 7}, {"greydark", 8}};
  auto it = names.find(name);
  if (it == names.end()) return false;
  *out = Palette16(it->second);
  return true;
}

std::string Color::Print(bool background) const {
  switch (type_) {
    case Type::Default: return background ? "49" : "39";
    case Type::Palette16: {
      int base = r_ < 8 ? (background ? 40 : 30) + r_ : (background ? 100 : 90) + (r_ - 8);
      return std::to_string(base);
    }
    case Type::Palette256: return (background ? "48;5;" : "38;5;") + std::to_string(r_);
    case Type::TrueColor:
      return (background ? "48;2;" : "38;2;") + std::to_string(r_) + ";" + std::to_string(g_) + ";" + std::to_string(b_);
  }
  return "39";
}

