}

const char* FindChar(int l, int r, int u, int d) {
  for (const auto& c : kChars)
    if (c.l == l && c.r == r && c.u == u && c.d == d) return c.ch;
  return nullptr;
}

int Norm(int s) { return s == 9 ? 1 : s; }

void UpgradeLeftRight(std::string& left, std::string& right) {
  const CharInfo* li = GetCharInfo(left);
  const CharInfo* ri = GetCharInfo(right);
  if (!li || !ri) return;
  if (li->r == 0 && ri->l != 0) {
    if (const char* c = FindChar(Norm(li->l), Norm(ri->l), Norm(li->u), Norm(li->d))) left = c;
  }
  if (ri->l == 0 && li->r != 0) {
    if (const char* c = FindChar(Norm(li->r), Norm(ri->r), Norm(ri->u), Norm(ri->d))) right = c;
  }
}

void UpgradeTopDown(std::string& top, std::string& down) {
  const CharInfo* ti = GetCharInfo(top);
  const CharInfo* di = GetCharInfo(down);
  if (!ti || !di) return;
  if (ti->d == 0 && di->u != 0) {
    if (const char* c = FindChar(Norm(ti->l), Norm(ti->r), Norm(ti->u), Norm(di->u))) top = c;
  }
  if (di->u == 0 && ti->d != 0) {
    if (const char* c = FindChar(Norm(di->l), Norm(di->r), Norm(ti->d), Norm(di->d))) down = c;
