}

void UpdatePixelStyle(std::string& out, Pixel& prev, const Pixel& next) {
  if (next.SameStyle(prev)) return;
  if ((!next.bold && prev.bold) || (!next.dim && prev.dim)) {
    out += "\x1b[22m";
    prev.bold = false;
    prev.dim = false;
  }
  if (next.bold && !prev.bold) out += "\x1b[1m";
  if (next.dim && !prev.dim) out += "\x1b[2m";
  if (next.italic != prev.italic) out += next.italic ? "\x1b[3m" : "\x1b[23m";
  if (next.underlined != prev.underlined) out += next.underlined ? "\x1b[4m" : "\x1b[24m";
  if (next.blink != prev.blink) out += next.blink ? "\x1b[5m" : "\x1b[25m";
  if (next.inverted != prev.inverted) out += next.inverted ? "\x1b[7m" : "\x1b[27m";
  if (next.strikethrough != prev.strikethrough) out += next.strikethrough ? "\x1b[9m" : "\x1b[29m";
  if (next.foreground_color != prev.foreground_color || next.background_color != prev.background_color) {
    out += "\x1b[" + next.foreground_color.Print(false) + "m";
    out += "\x1b[" + next.background_color.Print(true) + "m";
  }
  prev = next;
}

}  // namespace

void Screen::ApplyShader() {
  for (int y = 1; y < dimy_; ++y) {
    for (int x = 1; x < dimx_; ++x) {
      Pixel& cur = pixels_[y][x];
      if (cur.character.size() != 3U || !cur.automerge) continue;
      Pixel& left = pixels_[y][x - 1];
      if (left.character.size() == 3U && left.automerge) UpgradeLeftRight(left.character, cur.character);
      Pixel& top = pixels_[y - 1][x];
      if (top.character.size() == 3U && top.automerge) UpgradeTopDown(top.character, cur.character);
    }
  }
}

std::string Screen::ToString() const {
  std::string out;
  Pixel previous;
  const Pixel final_pixel;
  for (int y = 0; y < dimy_; ++y) {
    if (y != 0) {
      UpdatePixelStyle(out, previous, final_pixel);
      out += "\r\n";
    }
    bool previous_fullwidth = false;
    for (const auto& pixel : pixels_[y]) {
      if (!previous_fullwidth) {
        UpdatePixelStyle(out, previous, pixel);
        out += pixel.character;
      }
      previous_fullwidth = (string_width(pixel.character) == 2);
    }
  }
  UpdatePixelStyle(out, previous, final_pixel);
  return out;
}

}  // namespace tui
