Color Color::Palette256(int index) {
  index &= 255;
  if (TerminalSupport() == Support::Palette16) return Palette16(kPalette256To16[index]);
  Color c;
  c.type_ = Type::Palette256;
  c.r_ = static_cast<uint8_t>(index);
