// ---------------------------------------------------------------- unicode
static int Utf8Decode(const std::string& s, size_t& i, uint32_t& cp) {
  unsigned char c = s[i];
  int len = 1;
  if (c < 0x80) { cp = c; }
  else if ((c & 0xE0) == 0xC0) { cp = c & 0x1F; len = 2; }
  else if ((c & 0xF0) == 0xE0) { cp = c & 0x0F; len = 3; }
  else if ((c & 0xF8) == 0xF0) { cp = c & 0x07; len = 4; }
  else { cp = c; len = 1; }
  if (i + len > s.size()) { len = 1; cp = c; }
  for (int k = 1; k < len; ++k) {
    unsigned char cc = s[i + k];
    if ((cc & 0xC0) != 0x80) { len = 1; cp = c; break; }
    cp = (cp << 6) | (cc & 0x3F);
  }
  i += len;
  return len;
}

static bool InRange(uint32_t cp, uint32_t a, uint32_t b) { return cp >= a && cp <= b; }

int wcwidth_cp(uint32_t cp) {
  if (cp == 0) return 0;
  if (cp < 32 || (cp >= 0x7f && cp < 0xa0)) return 0;
  // combining marks
  if (InRange(cp, 0x0300, 0x036F) || InRange(cp, 0x0483, 0x0489) || InRange(cp, 0x0591, 0x05BD) ||
      InRange(cp, 0x0610, 0x061A) || InRange(cp, 0x064B, 0x065F) || InRange(cp, 0x1AB0, 0x1AFF) ||
      InRange(cp, 0x1DC0, 0x1DFF) || InRange(cp, 0x200B, 0x200F) || InRange(cp, 0x20D0, 0x20FF) ||
      InRange(cp, 0xFE00, 0xFE0F) || InRange(cp, 0xFE20, 0xFE2F) || cp == 0x200D)
    return 0;
  // wide
  if (InRange(cp, 0x1100, 0x115F) || InRange(cp, 0x2E80, 0x303E) || InRange(cp, 0x3041, 0x33FF) ||
      InRange(cp, 0x3400, 0x4DBF) || InRange(cp, 0x4E00, 0x9FFF) || InRange(cp, 0xA000, 0xA4CF) ||
      InRange(cp, 0xAC00, 0xD7A3) || InRange(cp, 0xF900, 0xFAFF) || InRange(cp, 0xFE30, 0xFE4F) ||
      InRange(cp, 0xFF00, 0xFF60) || InRange(cp, 0xFFE0, 0xFFE6) || InRange(cp, 0x1F300, 0x1F64F) ||
      InRange(cp, 0x1F900, 0x1F9FF) || InRange(cp, 0x20000, 0x2FFFD) || InRange(cp, 0x30000, 0x3FFFD) ||
      InRange(cp, 0x1F680, 0x1F6FF) || InRange(cp, 0x2600, 0x26FF) == false ? false : false)
    return 2;
  if (InRange(cp, 0x1F300, 0x1F64F) || InRange(cp, 0x1F900, 0x1F9FF) || InRange(cp, 0x1F680, 0x1F6FF) ||
      InRange(cp, 0x1F1E6, 0x1F1FF))
    return 2;
  return 1;
}

std::vector<std::string> utf8_glyphs(const std::string& s) {
  std::vector<std::string> out;
  size_t i = 0;
  while (i < s.size()) {
    size_t start = i;
    uint32_t cp;
    Utf8Decode(s, i, cp);
    int w = wcwidth_cp(cp);
    if (w == 0 && !out.empty()) {
      out.back() += s.substr(start, i - start);
    } else {
      out.push_back(s.substr(start, i - start));
    }
  }
  return out;
}

int string_width(const std::string& s) {
  int width = 0;
  size_t i = 0;
  while (i < s.size()) {
    uint32_t cp;
    Utf8Decode(s, i, cp);
    width += wcwidth_cp(cp);
  }
  return width;
}

static int glyph_width(const std::string& g) {
  size_t i = 0;
  uint32_t cp;
  if (g.empty()) return 0;
  Utf8Decode(g, i, cp);
  return wcwidth_cp(cp);
}

// ---------------------------------------------------------------- Node
void Node::ComputeRequirement() {
  for (auto& child : children_) child->ComputeRequirement();
}
void Node::SetBox(Box box) { box_ = box; }
void Node::Render(Screen& screen) {
  for (auto& child : children_) child->Render(screen);
}
void Node::Check(Status* status) {
  for (auto& child : children_) child->Check(status);
  status->need_iteration |= (status->iteration == 0);
}

void Render(Screen& screen, const Element& element) {
  Box box{0, screen.dimx() - 1, 0, screen.dimy() - 1};
  Node::Status status;
  element->Check(&status);
  const int max_iterations = 20;
  while (status.need_iteration && status.iteration < max_iterations) {
    element->ComputeRequirement();
    element->SetBox(box);
    status.need_iteration = false;
    status.iteration++;
    element->Check(&status);
  }
  screen.SetStencil(box.x_min, box.x_max, box.y_min, box.y_max);
  element->Render(screen);
  screen.ApplyShader();
}

