class Text : public Node {
 public:
  explicit Text(std::string s) : text_(std::move(s)) {}
  void ComputeRequirement() override {
    requirement_.min_x = string_width(text_);
    requirement_.min_y = 1;
  }
  void Render(Screen& screen) override {
    int x = box_.x_min;
    const int y = box_.y_min;
    if (y > box_.y_max) return;
    for (const auto& glyph : utf8_glyphs(text_)) {
      if (x > box_.x_max) return;
      int w = glyph_width(glyph);
      screen.PixelAt(x, y).character = glyph;
      if (w == 2 && x + 1 <= box_.x_max) {
        screen.PixelAt(x + 1, y).character = "";
      }
      x += std::max(w, 1);
    }
  }
 private:
  std::string text_;
};

