// ---------------------------------------------------------------- box helper
struct BoxElement { int min_size = 0; int flex_grow = 0; int flex_shrink = 0; int size = 0; };

void ComputeGrow(std::vector<BoxElement>& elements, int extra_space, int flex_grow_sum) {
  for (auto& e : elements) {
    int added = extra_space * e.flex_grow / std::max(flex_grow_sum, 1);
    extra_space -= added;
    flex_grow_sum -= e.flex_grow;
    e.size = e.min_size + added;
  }
}
void ComputeShrinkEasy(std::vector<BoxElement>& elements, int extra_space, int flex_shrink_sum) {
  for (auto& e : elements) {
    int added = extra_space * e.min_size * e.flex_shrink / std::max(flex_shrink_sum, 1);
    extra_space -= added;
    flex_shrink_sum -= e.flex_shrink * e.min_size;
    e.size = e.min_size + added;
  }
}
void ComputeShrinkHard(std::vector<BoxElement>& elements, int extra_space, int size) {
  for (auto& e : elements) {
    if (e.flex_shrink != 0) { e.size = 0; continue; }
    int added = extra_space * e.min_size / std::max(size, 1);
    extra_space -= added;
    size -= e.min_size;
    e.size = e.min_size + added;
  }
}
void ComputeBoxes(std::vector<BoxElement>& elements, int target_size) {
  int size = 0, flex_grow_sum = 0, flex_shrink_sum = 0, flex_shrink_size = 0;
  for (auto& e : elements) {
    flex_grow_sum += e.flex_grow;
    flex_shrink_sum += e.min_size * e.flex_shrink;
    if (e.flex_shrink != 0) flex_shrink_size += e.min_size;
    size += e.min_size;
  }
  int extra_space = target_size - size;
  if (extra_space >= 0) ComputeGrow(elements, extra_space, flex_grow_sum);
  else if (flex_shrink_size + extra_space >= 0) ComputeShrinkEasy(elements, extra_space, flex_shrink_sum);
  else ComputeShrinkHard(elements, extra_space + flex_shrink_size, size - flex_shrink_size);
}

// ---------------------------------------------------------------- vbox/hbox/dbox
class VBox : public Node {
 public:
  explicit VBox(Elements c) : Node(std::move(c)) {}
  void ComputeRequirement() override {
    requirement_ = Requirement();
    for (auto& child : children_) {
      child->ComputeRequirement();
      if (requirement_.selection < child->requirement().selection) {
        requirement_.selection = child->requirement().selection;
        requirement_.selected_box = child->requirement().selected_box;
        requirement_.selected_box.y_min += requirement_.min_y;
        requirement_.selected_box.y_max += requirement_.min_y;
      }
      requirement_.min_y += child->requirement().min_y;
      requirement_.min_x = std::max(requirement_.min_x, child->requirement().min_x);
    }
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    std::vector<BoxElement> elements(children_.size());
    for (size_t i = 0; i < children_.size(); ++i) {
      const auto& r = children_[i]->requirement();
      elements[i].min_size = r.min_y;
      elements[i].flex_grow = r.flex_grow_y;
      elements[i].flex_shrink = r.flex_shrink_y;
    }
    ComputeBoxes(elements, box.y_max - box.y_min + 1);
    int y = box.y_min;
    for (size_t i = 0; i < children_.size(); ++i) {
      box.y_min = y;
      box.y_max = y + elements[i].size - 1;
      children_[i]->SetBox(box);
      y = box.y_max + 1;
    }
  }
};

