};

// ---------------------------------------------------------------- size
class Size : public Node {
 public:
  Size(Element child, WidthOrHeight d, Constraint c, int v) : Node({std::move(child)}), direction_(d), constraint_(c), value_(v) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
    int& value = direction_ == WIDTH ? requirement_.min_x : requirement_.min_y;
    switch (constraint_) {
      case LESS_THAN: value = std::min(value, value_); break;
      case EQUAL: value = value_; break;
      case GREATER_THAN: value = std::max(value, value_); break;
    }
    if (direction_ == WIDTH) { requirement_.flex_grow_x = 0; requirement_.flex_shrink_x = 0; }
    else { requirement_.flex_grow_y = 0; requirement_.flex_shrink_y = 0; }
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    if (direction_ == WIDTH) {
      if (constraint_ != GREATER_THAN) box.x_max = std::min(box.x_min + value_ - 1, box.x_max);
    } else {
      if (constraint_ != GREATER_THAN) box.y_max = std::min(box.y_min + value_ - 1, box.y_max);
    }
    children_[0]->SetBox(box);
  }
 private:
  WidthOrHeight direction_;
  Constraint constraint_;
  int value_;
};

// ---------------------------------------------------------------- border
struct Charset { const char* tl; const char* tr; const char* bl; const char* br; const char* h; const char* v; };
const Charset kCharsets[] = {
    {"┌", "┐", "└", "┘", "─", "│"},   // LIGHT
    {"┏", "┓", "┗", "┛", "╍", "╏"},   // DASHED
    {"┏", "┓", "┗", "┛", "━", "┃"},   // HEAVY
    {"╔", "╗", "╚", "╝", "═", "║"},   // DOUBLE
    {"╭", "╮", "╰", "╯", "─", "│"},   // ROUNDED
    {" ", " ", " ", " ", " ", " "},   // EMPTY
};

class Border : public Node {
 public:
  Border(Elements children, BorderStyle style) : Node(std::move(children)), charset_(kCharsets[style]) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
    requirement_.min_x += 2;
    requirement_.min_y += 2;
    if (children_.size() == 2) {
      requirement_.min_x = std::max(requirement_.min_x, children_[1]->requirement().min_x + 2);
    }
    requirement_.selected_box.Shift(1, 1);
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    if (children_.size() == 2) {
      Box title_box;
      title_box.x_min = box.x_min + 1;
      title_box.x_max = box.x_max - 1;
      title_box.y_min = box.y_min;
      title_box.y_max = box.y_min;
      children_[1]->SetBox(title_box);
    }
    box.x_min++; box.x_max--; box.y_min++; box.y_max--;
    children_[0]->SetBox(box);
  }
  void Render(Screen& screen) override {
    children_[0]->Render(screen);
    if (box_.x_min >= box_.x_max || box_.y_min >= box_.y_max) return;
    screen.at(box_.x_min, box_.y_min) = charset_.tl;
    screen.at(box_.x_max, box_.y_min) = charset_.tr;
    screen.at(box_.x_min, box_.y_max) = charset_.bl;
    screen.at(box_.x_max, box_.y_max) = charset_.br;
    for (int x = box_.x_min + 1; x < box_.x_max; ++x) {
      Pixel& p1 = screen.PixelAt(x, box_.y_min);
      Pixel& p2 = screen.PixelAt(x, box_.y_max);
      p1.character = charset_.h; p1.automerge = true;
      p2.character = charset_.h; p2.automerge = true;
    }
    for (int y = box_.y_min + 1; y < box_.y_max; ++y) {
      Pixel& p3 = screen.PixelAt(box_.x_min, y);
      Pixel& p4 = screen.PixelAt(box_.x_max, y);
      p3.character = charset_.v; p3.automerge = true;
      p4.character = charset_.v; p4.automerge = true;
    }
    if (children_.size() == 2) children_[1]->Render(screen);
  }
 private:
  Charset charset_;
};

// ---------------------------------------------------------------- separator
class Separator : public Node {
 public:
  explicit Separator(bool empty) : empty_(empty) {}
  void ComputeRequirement() override { requirement_.min_x = 1; requirement_.min_y = 1; }
  void Render(Screen& screen) override {
    const bool is_column = (box_.x_max == box_.x_min);
    const bool is_line = (box_.y_min == box_.y_max);
    const char* c = empty_ ? " " : ((is_line && !is_column) ? "─" : "│");
    for (int y = box_.y_min; y <= box_.y_max; ++y)
      for (int x = box_.x_min; x <= box_.x_max; ++x) {
        Pixel& p = screen.PixelAt(x, y);
        p.character = c;
        p.automerge = true;
      }
  }
 private:
  bool empty_;
};

// ---------------------------------------------------------------- decorators
class NodeDecorator : public Node {
 public:
  explicit NodeDecorator(Element child) : Node({std::move(child)}) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
