  void SetBox(Box box) override {
    Node::SetBox(box);
    children_[0]->SetBox(box);
  }
};

class StyleDecorator : public NodeDecorator {
 public:
  StyleDecorator(Element child, std::function<void(Pixel&)> f) : NodeDecorator(std::move(child)), f_(std::move(f)) {}
  void Render(Screen& screen) override {
    Node::Render(screen);
    for (int y = box_.y_min; y <= box_.y_max; ++y)
      for (int x = box_.x_min; x <= box_.x_max; ++x) f_(screen.PixelAt(x, y));
  }
 private:
  std::function<void(Pixel&)> f_;
};

class ClearUnder : public NodeDecorator {
 public:
  using NodeDecorator::NodeDecorator;
  void Render(Screen& screen) override {
    for (int y = box_.y_min; y <= box_.y_max; ++y)
