  void SetBox(Box box) override {
    Node::SetBox(box);
    auto& selected_box = requirement_.selected_box;
    Box children_box = box;
    if (x_frame_) {
      const int external_dimx = box.x_max - box.x_min;
      const int internal_dimx = std::max(requirement_.min_x - 1, external_dimx);
      const int focused_dimx = selected_box.x_max - selected_box.x_min;
      int dx = selected_box.x_min - external_dimx / 2 + focused_dimx / 2;
      dx = std::max(0, std::min(internal_dimx - external_dimx, dx));
      children_box.x_min = box.x_min - dx;
      children_box.x_max = box.x_min + internal_dimx - dx;
    }
    if (y_frame_) {
      const int external_dimy = box.y_max - box.y_min;
      const int internal_dimy = std::max(requirement_.min_y - 1, external_dimy);
      const int focused_dimy = selected_box.y_max - selected_box.y_min;
      int dy = selected_box.y_min - external_dimy / 2 + focused_dimy / 2;
      dy = std::max(0, std::min(internal_dimy - external_dimy, dy));
      children_box.y_min = box.y_min - dy;
      children_box.y_max = box.y_min + internal_dimy - dy;
    }
    children_[0]->SetBox(children_box);
  }
  void Render(Screen& screen) override {
    int sx0 = screen.stencil_x_min, sx1 = screen.stencil_x_max, sy0 = screen.stencil_y_min, sy1 = screen.stencil_y_max;
    screen.SetStencil(std::max(sx0, box_.x_min), std::min(sx1, box_.x_max), std::max(sy0, box_.y_min), std::min(sy1, box_.y_max));
    children_[0]->Render(screen);
    screen.SetStencil(sx0, sx1, sy0, sy1);
  }
 private:
  bool x_frame_, y_frame_;
};

class VScrollIndicator : public NodeDecorator {
 public:
  using NodeDecorator::NodeDecorator;
  void ComputeRequirement() override {
    NodeDecorator::ComputeRequirement();
    requirement_.min_x++;
  }
  void SetBox(Box box) override {
    box_ = box;
    box.x_max--;
    children_[0]->SetBox(box);
  }
  void Render(Screen& screen) override {
    Node::Render(screen);
    const int size_inner = box_.y_max - box_.y_min;
    if (size_inner <= 0) return;
    const int stencil_y_min = screen.stencil_y_min, stencil_y_max = screen.stencil_y_max;
    const int size_outter = stencil_y_max - stencil_y_min + 1;
    if (size_outter >= size_inner) return;
    int size = 2 * size_outter * size_outter / size_inner;
    size = std::max(size, 1);
    const int start_y = 2 * stencil_y_min + 2 * (stencil_y_min - box_.y_min) * size_outter / size_inner;
    const int x = screen.stencil_x_max;
    for (int y = stencil_y_min; y <= stencil_y_max; ++y) {
      const int y_up = 2 * y + 0;
      const int y_down = 2 * y + 1;
      const bool up = (start_y <= y_up) && (y_up < start_y + size);
      const bool down = (start_y <= y_down) && (y_down < start_y + size);
      const char* c = up ? (down ? "┃" : "╹") : (down ? "╻" : " ");
      screen.PixelAt(x, y).character = c;
    }
  }
};

