struct termios g_original;
bool g_have_original = false;
int g_signal_pipe[2] = {-1, -1};

void OnSignal(int sig) {
  char c = static_cast<char>(sig);
  if (g_signal_pipe[1] >= 0) {
    ssize_t r = write(g_signal_pipe[1], &c, 1);
    (void)r;
  }
}

void WriteAll(const std::string& s) {
  size_t off = 0;
  while (off < s.size()) {
    ssize_t n = write(STDOUT_FILENO, s.data() + off, s.size() - off);
    if (n <= 0) return;
    off += n;
  }
}
}  // namespace

Terminal::Terminal() {
  if (g_signal_pipe[0] < 0) {
    if (pipe(g_signal_pipe) == 0) {
      signal(SIGWINCH, OnSignal);
    }
  }
}

Terminal::~Terminal() { Uninstall(); }

void Terminal::Size(int* dimx, int* dimy) {
  winsize w{};
  if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &w) == 0 && w.ws_col > 0 && w.ws_row > 0) {
    *dimx = w.ws_col;
    *dimy = w.ws_row;
    return;
  }
  const char* c = getenv("COLUMNS");
  const char* l = getenv("LINES");
  *dimx = c ? atoi(c) : 80;
  *dimy = l ? atoi(l) : 24;
  if (*dimx <= 0) *dimx = 80;
  if (*dimy <= 0) *dimy = 24;
}

void Terminal::Install() {
  if (installed_) return;
  installed_ = true;
  if (tcgetattr(STDIN_FILENO, &g_original) == 0) {
    g_have_original = true;
    struct termios raw = g_original;
    raw.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    raw.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    raw.c_cflag &= ~(CSIZE | PARENB);
    raw.c_cflag |= CS8;
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &raw);
  }
  std::string s;
  s += "\x1bP$q q\x1b\\";
  s += "\x1b[?1049h";
  s += "\x1b[?7l";
  s += "\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h";
  WriteAll(s);
  previous_dimy_ = 0;
  reset_cursor_position_.clear();
}

void Terminal::Uninstall() {
  if (!installed_) return;
  installed_ = false;
  std::string s;
  s += reset_cursor_position_;
  s += "\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l";
  s += "\x1b[?7h";
  s += "\x1b[?1049l";
  s += "\x1b[?25h";
  s += "\x1b[1 q";
  WriteAll(s);
  if (g_have_original) tcsetattr(STDIN_FILENO, TCSANOW, &g_original);
  reset_cursor_position_.clear();
}

void Terminal::Draw(const Screen& screen) {
  std::string out;
  out += reset_cursor_position_;
  // reset position
  out += "\r";
  if (previous_dimy_ == 0) {
    out += "\x1b[2K";
  } else {
    for (int i = 0; i < previous_dimy_ - 1; ++i) out += "\x1b[1A";
  }
  out += screen.ToString();
  // cursor
  int dimx = screen.dimx(), dimy = screen.dimy();
  int cx = screen.cursor.x, cy = screen.cursor.y;
  int dx = dimx - 1 - cx;
  int dy = dimy - 1 - cy;
  std::string set, reset;
  if (dy != 0) { set += "\x1b[" + std::to_string(dy) + "A"; reset += "\x1b[" + std::to_string(dy) + "B"; }
  if (dx != 0) { set += "\x1b[" + std::to_string(dx) + "D"; reset += "\x1b[" + std::to_string(dx) + "C"; }
  if (screen.cursor.hidden) set += "\x1b[?25l";
  else set += "\x1b[?25h\x1b[1 q";
  out += set;
  reset_cursor_position_ = reset;
  previous_dimy_ = dimy;
  WriteAll(out);
}

