bool IsDigit(char c) { return c >= '0' && c <= '9'; }

// Try to parse one complete event from the buffer. Returns number of bytes consumed (0 = incomplete).
size_t ParseOne(const std::string& buf, Event* ev, bool timeout) {
  if (buf.empty()) return 0;
  unsigned char c = buf[0];
  if (c == 0x1b) {
    if (buf.size() == 1) {
      if (timeout) { *ev = events::Escape; return 1; }
      return 0;
    }
    char n = buf[1];
    if (n == '[') {
      // CSI
      size_t i = 2;
      while (i < buf.size() && ((buf[i] >= 0x30 && buf[i] <= 0x3f))) ++i;  // params
      while (i < buf.size() && ((buf[i] >= 0x20 && buf[i] <= 0x2f))) ++i;  // intermediates
      if (i >= buf.size()) { if (timeout) { *ev = events::Escape; return 1; } return 0; }
      char fin = buf[i];
      std::string params = buf.substr(2, i - 2);
      std::string raw = buf.substr(0, i + 1);
      *ev = Event::Key("Unknown", raw);
      if (fin == 'A') *ev = events::ArrowUp;
      else if (fin == 'B') *ev = events::ArrowDown;
      else if (fin == 'C') *ev = events::ArrowRight;
      else if (fin == 'D') *ev = events::ArrowLeft;
      else if (fin == 'H') *ev = events::Home;
      else if (fin == 'F') *ev = events::End;
      else if (fin == 'Z') *ev = events::TabReverse;
      else if (fin == '~') {
        int num = atoi(params.c_str());
        switch (num) {
          case 1: case 7: *ev = events::Home; break;
          case 2: *ev = events::Insert; break;
          case 3: *ev = events::Delete; break;
          case 4: case 8: *ev = events::End; break;
          case 5: *ev = events::PageUp; break;
          case 6: *ev = events::PageDown; break;
          case 11: *ev = events::F1; break;
          case 12: *ev = Event::Key("F2"); break;
          case 13: *ev = Event::Key("F3"); break;
          case 14: *ev = Event::Key("F4"); break;
          case 15: *ev = Event::Key("F5"); break;
          case 17: *ev = Event::Key("F6"); break;
          case 18: *ev = Event::Key("F7"); break;
          case 19: *ev = Event::Key("F8"); break;
          case 20: *ev = Event::Key("F9"); break;
          case 21: *ev = Event::Key("F10"); break;
          case 23: *ev = Event::Key("F11"); break;
          case 24: *ev = Event::Key("F12"); break;
          default: break;
        }
      } else if ((fin == 'M' || fin == 'm') && !params.empty() && params[0] == '<') {
        // SGR mouse
        int b = 0, x = 0, y = 0;
        sscanf(params.c_str() + 1, "%d;%d;%d", &b, &x, &y);
        Event m; m.type = Event::Mouse; m.mouse_button = b; m.mouse_x = x - 1; m.mouse_y = y - 1; m.mouse_press = (fin == 'M'); m.input = raw;
        *ev = m;
      } else if (fin == 'P') *ev = events::F1;
      else if (fin == 'Q') *ev = Event::Key("F2");
      else if (fin == 'R') *ev = Event::Key("F3");
      else if (fin == 'S') *ev = Event::Key("F4");
      return i + 1;
    }
    if (n == 'O') {
      if (buf.size() < 3) { if (timeout) { *ev = events::Escape; return 1; } return 0; }
      char f = buf[2];
      std::string raw = buf.substr(0, 3);
      *ev = Event::Key("Unknown", raw);
      switch (f) {
        case 'A': *ev = events::ArrowUp; break;
        case 'B': *ev = events::ArrowDown; break;
        case 'C': *ev = events::ArrowRight; break;
        case 'D': *ev = events::ArrowLeft; break;
        case 'H': *ev = events::Home; break;
        case 'F': *ev = events::End; break;
        case 'P': *ev = events::F1; break;
        case 'Q': *ev = Event::Key("F2"); break;
        case 'R': *ev = Event::Key("F3"); break;
        case 'S': *ev = Event::Key("F4"); break;
        default: break;
      }
      return 3;
    }
    if (n == 'P' || n == ']' || n == '_' || n == '^') {
      // DCS / OSC: terminated by ESC \ or BEL
      size_t pos = buf.find("\x1b\\", 2);
      size_t pos2 = buf.find('\x07', 2);
      size_t end = std::string::npos;
      size_t len = 0;
      if (pos != std::string::npos) { end = pos; len = 2; }
      if (pos2 != std::string::npos && (end == std::string::npos || pos2 < end)) { end = pos2; len = 1; }
      if (end == std::string::npos) { if (timeout) { *ev = events::Escape; return 1; } return 0; }
      *ev = Event::Key("Unknown", buf.substr(0, end + len));
      return end + len;
    }
    // ESC + char: treat as Escape followed by char (alt-key). Return escape alone.
    *ev = events::Escape;
    return 1;
  }
  if (c == '\r' || c == '\n') { *ev = events::Return; return 1; }
  if (c == '\t') { *ev = events::Tab; return 1; }
  if (c == 0x7f || c == 0x08) { *ev = events::Backspace; return 1; }
  if (c == 0x03) { *ev = events::CtrlC; return 1; }
  if (c < 0x20) { *ev = Event::Key("Ctrl", std::string(1, static_cast<char>(c))); return 1; }
  // UTF-8 character
  size_t len = 1;
  if ((c & 0xE0) == 0xC0) len = 2;
  else if ((c & 0xF0) == 0xE0) len = 3;
  else if ((c & 0xF8) == 0xF0) len = 4;
  if (buf.size() < len) { if (timeout) { *ev = Event::Char(buf.substr(0, 1)); return 1; } return 0; }
  *ev = Event::Char(buf.substr(0, len));
  return len;
}

}  // namespace

bool Terminal::ParsePending(Event* event, bool timeout) {
  size_t n = ParseOne(pending_, event, timeout);
  if (n == 0) return false;
  pending_.erase(0, n);
  return true;
}

bool Terminal::NextEvent(Event* event) {
  while (true) {
    if (ParsePending(event, false)) return true;
    struct pollfd fds[2];
    fds[0].fd = STDIN_FILENO; fds[0].events = POLLIN;
    fds[1].fd = g_signal_pipe[0]; fds[1].events = POLLIN;
