namespace events {
const Event ArrowUp = Event::Key("ArrowUp");
const Event ArrowDown = Event::Key("ArrowDown");
const Event ArrowLeft = Event::Key("ArrowLeft");
const Event ArrowRight = Event::Key("ArrowRight");
const Event Return = Event::Key("Return");
const Event Escape = Event::Key("Escape");
const Event Tab = Event::Key("Tab");
const Event TabReverse = Event::Key("TabReverse");
const Event Backspace = Event::Key("Backspace");
const Event Delete = Event::Key("Delete");
const Event Home = Event::Key("Home");
const Event End = Event::Key("End");
const Event PageUp = Event::Key("PageUp");
const Event PageDown = Event::Key("PageDown");
const Event F1 = Event::Key("F1");
const Event CtrlC = Event::Key("CtrlC");
const Event Resize = [] { Event e; e.type = Event::Resize; return e; }();
const Event Insert = Event::Key("Insert");
}  // namespace events

namespace {
struct termios g_original;
bool g_have_original = false;
int g_signal_pipe[2] = {-1, -1};

void OnSignal(int sig) {
  char c = static_cast<char>(sig);
  if (g_signal_pipe[1] >= 0) {
    ssize_t r = write(g_signal_pipe[1], &c, 1);
    (void)r;
  }
}

void WriteAll(const std::string& s) {
  size_t off = 0;
  while (off < s.size()) {
    ssize_t n = write(STDOUT_FILENO, s.data() + off, s.size() - off);
    if (n <= 0) return;
    off += n;
  }
}
}  // namespace

Terminal::Terminal() {
  if (g_signal_pipe[0] < 0) {
    if (pipe(g_signal_pipe) == 0) {
      signal(SIGWINCH, OnSignal);
    }
  }
}

Terminal::~Terminal() { Uninstall(); }

void Terminal::Size(int* dimx, int* dimy) {
  winsize w{};
  if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &w) == 0 && w.ws_col > 0 && w.ws_row > 0) {
    *dimx = w.ws_col;
    *dimy = w.ws_row;
    return;
  }
  const char* c = getenv("COLUMNS");
  const char* l = getenv("LINES");
  *dimx = c ? atoi(c) : 80;
  *dimy = l ? atoi(l) : 24;
  if (*dimx <= 0) *dimx = 80;
  if (*dimy <= 0) *dimy = 24;
}

void Terminal::Install() {
  if (installed_) return;
  installed_ = true;
  if (tcgetattr(STDIN_FILENO, &g_original) == 0) {
    g_have_original = true;
    struct termios raw = g_original;
    raw.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    raw.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    raw.c_cflag &= ~(CSIZE | PARENB);
    raw.c_cflag |= CS8;
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSANOW, &raw);
  }
  std::string s;
  s += "\x1bP$q q\x1b\\";
  s += "\x1b[?1049h";
  s += "\x1b[?7l";
  s += "\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h";
  WriteAll(s);
  previous_dimy_ = 0;
  reset_cursor_position_.clear();
}

void Terminal::Uninstall() {
  if (!installed_) return;
  installed_ = false;
  std::string s;
  s += reset_cursor_position_;
  s += "\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l";
  s += "\x1b[?7h";
  s += "\x1b[?1049l";
  s += "\x1b[?25h";
  s += "\x1b[1 q";
  WriteAll(s);
  if (g_have_original) tcsetattr(STDIN_FILENO, TCSANOW, &g_original);
  reset_cursor_position_.clear();
}

void Terminal::Draw(const Screen& screen) {
  std::string out;
  out += reset_cursor_position_;
  // reset position
  out += "\r";
  if (previous_dimy_ == 0) {
    out += "\x1b[2K";
  } else {
    for (int i = 0; i < previous_dimy_ - 1; ++i) out += "\x1b[1A";
  }
  out += screen.ToString();
  // cursor
  int dimx = screen.dimx(), dimy = screen.dimy();
  int cx = screen.cursor.x, cy = screen.cursor.y;
  int dx = dimx - 1 - cx;
  int dy = dimy - 1 - cy;
  std::string set, reset;
  if (dy != 0) { set += "\x1b[" + std::to_string(dy) + "A"; reset += "\x1b[" + std::to_string(dy) + "B"; }
  if (dx != 0) { set += "\x1b[" + std::to_string(dx) + "D"; reset += "\x1b[" + std::to_string(dx) + "C"; }
  if (screen.cursor.hidden) set += "\x1b[?25l";
  else set += "\x1b[?25h\x1b[1 q";
  out += set;
  reset_cursor_position_ = reset;
  previous_dimy_ = dimy;
  WriteAll(out);
}

namespace {

bool IsDigit(char c) { return c >= '0' && c <= '9'; }

// Try to parse one complete event from the buffer. Returns number of bytes consumed (0 = incomplete).
size_t ParseOne(const std::string& buf, Event* ev, bool timeout) {
  if (buf.empty()) return 0;
  unsigned char c = buf[0];
  if (c == 0x1b) {
    if (buf.size() == 1) {
      if (timeout) { *ev = events::Escape; return 1; }
      return 0;
    }
    char n = buf[1];
    if (n == '[') {
      // CSI
      size_t i = 2;
      while (i < buf.size() && ((buf[i] >= 0x30 && buf[i] <= 0x3f))) ++i;  // params
      while (i < buf.size() && ((buf[i] >= 0x20 && buf[i] <= 0x2f))) ++i;  // intermediates
      if (i >= buf.size()) { if (timeout) { *ev = events::Escape; return 1; } return 0; }
      char fin = buf[i];
      std::string params = buf.substr(2, i - 2);
      std::string raw = buf.substr(0, i + 1);
      *ev = Event::Key("Unknown", raw);
      if (fin == 'A') *ev = events::ArrowUp;
      else if (fin == 'B') *ev = events::ArrowDown;
      else if (fin == 'C') *ev = events::ArrowRight;
      else if (fin == 'D') *ev = events::ArrowLeft;
      else if (fin == 'H') *ev = events::Home;
      else if (fin == 'F') *ev = events::End;
      else if (fin == 'Z') *ev = events::TabReverse;
      else if (fin == '~') {
        int num = atoi(params.c_str());
        switch (num) {
          case 1: case 7: *ev = events::Home; break;
          case 2: *ev = events::Insert; break;
          case 3: *ev = events::Delete; break;
          case 4: case 8: *ev = events::End; break;
          case 5: *ev = events::PageUp; break;
          case 6: *ev = events::PageDown; break;
          case 11: *ev = events::F1; break;
          case 12: *ev = Event::Key("F2"); break;
          case 13: *ev = Event::Key("F3"); break;
          case 14: *ev = Event::Key("F4"); break;
          case 15: *ev = Event::Key("F5"); break;
          case 17: *ev = Event::Key("F6"); break;
          case 18: *ev = Event::Key("F7"); break;
          case 19: *ev = Event::Key("F8"); break;
          case 20: *ev = Event::Key("F9"); break;
          case 21: *ev = Event::Key("F10"); break;
          case 23: *ev = Event::Key("F11"); break;
          case 24: *ev = Event::Key("F12"); break;
          default: break;
        }
      } else if ((fin == 'M' || fin == 'm') && !params.empty() && params[0] == '<') {
        // SGR mouse
        int b = 0, x = 0, y = 0;
        sscanf(params.c_str() + 1, "%d;%d;%d", &b, &x, &y);
        Event m; m.type = Event::Mouse; m.mouse_button = b; m.mouse_x = x - 1; m.mouse_y = y - 1; m.mouse_press = (fin == 'M'); m.input = raw;
        *ev = m;
      } else if (fin == 'P') *ev = events::F1;
      else if (fin == 'Q') *ev = Event::Key("F2");
      else if (fin == 'R') *ev = Event::Key("F3");
      else if (fin == 'S') *ev = Event::Key("F4");
      return i + 1;
    }
    if (n == 'O') {
      if (buf.size() < 3) { if (timeout) { *ev = events::Escape; return 1; } return 0; }
      char f = buf[2];
      std::string raw = buf.substr(0, 3);
      *ev = Event::Key("Unknown", raw);
      switch (f) {
        case 'A': *ev = events::ArrowUp; break;
        case 'B': *ev = events::ArrowDown; break;
        case 'C': *ev = events::ArrowRight; break;
        case 'D': *ev = events::ArrowLeft; break;
        case 'H': *ev = events::Home; break;
        case 'F': *ev = events::End; break;
        case 'P': *ev = events::F1; break;
        case 'Q': *ev = Event::Key("F2"); break;
        case 'R': *ev = Event::Key("F3"); break;
        case 'S': *ev = Event::Key("F4"); break;
        default: break;
      }
      return 3;
    }
    if (n == 'P' || n == ']' || n == '_' || n == '^') {
      // DCS / OSC: terminated by ESC \ or BEL
      size_t pos = buf.find("\x1b\\", 2);
      size_t pos2 = buf.find('\x07', 2);
      size_t end = std::string::npos;
      size_t len = 0;
      if (pos != std::string::npos) { end = pos; len = 2; }
      if (pos2 != std::string::npos && (end == std::string::npos || pos2 < end)) { end = pos2; len = 1; }
      if (end == std::string::npos) { if (timeout) { *ev = events::Escape; return 1; } return 0; }
      *ev = Event::Key("Unknown", buf.substr(0, end + len));
      return end + len;
    }
    // ESC + char: treat as Escape followed by char (alt-key). Return escape alone.
    *ev = events::Escape;
    return 1;
  }
  if (c == '\r' || c == '\n') { *ev = events::Return; return 1; }
  if (c == '\t') { *ev = events::Tab; return 1; }
  if (c == 0x7f || c == 0x08) { *ev = events::Backspace; return 1; }
  if (c == 0x03) { *ev = events::CtrlC; return 1; }
  if (c < 0x20) { *ev = Event::Key("Ctrl", std::string(1, static_cast<char>(c))); return 1; }
  // UTF-8 character
  size_t len = 1;
  if ((c & 0xE0) == 0xC0) len = 2;
  else if ((c & 0xF0) == 0xE0) len = 3;
  else if ((c & 0xF8) == 0xF0) len = 4;
  if (buf.size() < len) { if (timeout) { *ev = Event::Char(buf.substr(0, 1)); return 1; } return 0; }
  *ev = Event::Char(buf.substr(0, len));
  return len;
}

}  // namespace

bool Terminal::ParsePending(Event* event, bool timeout) {
  size_t n = ParseOne(pending_, event, timeout);
  if (n == 0) return false;
  pending_.erase(0, n);
  return true;
}

bool Terminal::NextEvent(Event* event) {
  while (true) {
    if (ParsePending(event, false)) return true;
    struct pollfd fds[2];
    fds[0].fd = STDIN_FILENO; fds[0].events = POLLIN;
    fds[1].fd = g_signal_pipe[0]; fds[1].events = POLLIN;
    int nfds = g_signal_pipe[0] >= 0 ? 2 : 1;
    int timeout_ms = pending_.empty() ? -1 : 50;
    if (stdin_closed_) { fds[0].events = 0; timeout_ms = pending_.empty() ? -1 : 50; }
    int r = poll(fds, nfds, timeout_ms);
    if (r < 0) {
      if (errno == EINTR) continue;
      return false;
    }
    if (r == 0) {
      if (ParsePending(event, true)) return true;
      continue;
    }
    if (nfds == 2 && (fds[1].revents & POLLIN)) {
      char buf[16];
      ssize_t k = read(g_signal_pipe[0], buf, sizeof buf);
      (void)k;
      *event = events::Resize;
      return true;
    }
    if (fds[0].revents & (POLLIN | POLLHUP | POLLERR)) {
      char buf[256];
      ssize_t k = read(STDIN_FILENO, buf, sizeof buf);
      if (k <= 0) {
        stdin_closed_ = true;
        if (k == 0 || errno != EINTR) {
          if (pending_.empty()) return false;
        }
        continue;
      }
      pending_.append(buf, k);
    }
  }
}

}  // namespace tui
