namespace app {

namespace {
std::string trim(const std::string& s) {
  size_t a = 0, b = s.size();
  while (a < b && std::isspace(static_cast<unsigned char>(s[a]))) ++a;
  while (b > a && std::isspace(static_cast<unsigned char>(s[b - 1]))) --b;
  return s.substr(a, b - a);
}
std::string lower(std::string s) {
  for (auto& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
  return s;
}
std::vector<std::string> split(const std::string& s, char sep) {
  std::vector<std::string> out;
  std::string cur;
  for (char c : s) {
    if (c == sep) { out.push_back(cur); cur.clear(); }
    else cur += c;
  }
  out.push_back(cur);
  return out;
}
}  // namespace

const PTree* PTree::find(const std::string& key) const {
  for (const auto& c : children)
    if (c.first == key) return c.second.get();
  return nullptr;
}

const PTree* PTree::get_child_path(const std::string& path) const {
  const PTree* cur = this;
  for (const auto& part : split(path, '.')) {
    cur = cur->find(part);
    if (!cur) return nullptr;
  }
  return cur;
}

PTree* PTree::add_path(const std::string& path) {
  PTree* cur = this;
  auto parts = split(path, '.');
  for (size_t i = 0; i < parts.size(); ++i) {
    const auto& part = parts[i];
    PTree* next = nullptr;
    if (i + 1 < parts.size()) {
      for (auto& c : cur->children)
        if (c.first == part) { next = c.second.get(); break; }
    }
    if (!next) {
      auto node = std::make_shared<PTree>();
      cur->children.emplace_back(part, node);
      next = node.get();
    }
    cur = next;
  }
  return cur;
}

std::optional<std::string> PTree::get_string(const std::string& path) const {
  const PTree* c = get_child_path(path);
  if (!c) return std::nullopt;
  return c->data;
}

bool PTree::get_bool(const std::string& path, bool def) const {
  auto v = get_string(path);
  if (!v) return def;
  std::string s = trim(*v);
  if (s == "1" || s == "true") return true;
  if (s == "0" || s == "false") return false;
  return def;
}

int PTree::get_int(const std::string& path, int def) const {
  auto v = get_string(path);
  if (!v) return def;
  std::string s = trim(*v);
  if (s.empty()) return def;
  char* end = nullptr;
  long val = std::strtol(s.c_str(), &end, 10);
  if (end == s.c_str() || *end != '\0') return def;
  return static_cast<int>(val);
}

PTree parse_ini(const std::string& content) {
  PTree root;
  PTree* section = &root;
  std::istringstream in(content);
  std::string line;
  int line_no = 0;
  auto error = [&](const std::string& msg) {
    throw ParseError("<unspecified file>(" + std::to_string(line_no) + "): " + msg);
  };
  while (std::getline(in, line)) {
    ++line_no;
    line = trim(line);
    if (line.empty()) continue;
    if (line[0] == ';' || line[0] == '#') continue;
    if (line[0] == '[') {
      size_t end = line.find(']');
      if (end == std::string::npos) error("']' character not found in line");
      if (end + 1 != line.size()) error("characters after ']' are not allowed");  // approximation
      std::string name = trim(line.substr(1, end - 1));
      if (root.get_child_path(name)) error("duplicate section name");
      section = root.add_path(name);
    } else {
      size_t eq = line.find('=');
      if (eq == std::string::npos) error("'=' character not found in line");
      std::string key = trim(line.substr(0, eq));
      std::string value = trim(line.substr(eq + 1));
      if (key.empty()) error("key expected");
      if (section->find(key)) error("duplicate key name");
      auto node = std::make_shared<PTree>();
      node->data = value;
      section->children.emplace_back(key, node);
    }
  }
  return root;
}

