tui::Element Style::apply(tui::Element e) const {
  using namespace tui;
  if (fg) e = e | color(*fg);
  if (bg) e = e | bgcolor(*bg);
  if (bold) e = tui::bold(e);
  if (dim) e = tui::dim(e);
  if (underlined) e = tui::underlined(e);
