    if (t.empty()) return false;
    for (char c : t)
      if (!std::isdigit(static_cast<unsigned char>(c))) return false;
    vals.push_back(std::atoi(t.c_str()));
  }
  return true;
}

}  // namespace

tui::Color parse_color(const std::string& raw) {
  using tui::Color;
  std::string s = trim(raw);
  std::string l = lower(s);
  auto bad = [&]() { throw std::runtime_error("Invalid color: " + raw); };
  if (l == "default" || l.empty()) return Color::Default();
  if (s[0] == '#') {
    if (s.size() != 7) bad();
    for (size_t i = 1; i < 7; ++i)
      if (!std::isxdigit(static_cast<unsigned char>(s[i]))) bad();
    int r = std::stoi(s.substr(1, 2), nullptr, 16);
    int g = std::stoi(s.substr(3, 2), nullptr, 16);
    int b = std::stoi(s.substr(5, 2), nullptr, 16);
    return Color::RGB(r, g, b);
  }
  size_t open = l.find('(');
  size_t close = l.rfind(')');
  if (open == std::string::npos || close == std::string::npos || close < open) bad();
  std::string fn = trim(l.substr(0, open));
  std::string inside = trim(s.substr(open + 1, close - open - 1));
  std::vector<int> vals;
  if (fn == "rgb") {
    if (!parse_rgb_args(inside, vals) || vals.size() != 3) bad();
    for (int v : vals) if (v < 0 || v > 255) bad();
    return Color::RGB(vals[0], vals[1], vals[2]);
  }
  if (fn == "rgba") {
    if (!parse_rgb_args(inside, vals) || vals.size() != 4) bad();
    for (int v : vals) if (v < 0 || v > 255) bad();
    return Color::RGB(vals[0], vals[1], vals[2]);
  }
  if (fn == "ansi256") {
    if (!parse_rgb_args(inside, vals) || vals.size() != 1 || vals[0] < 0 || vals[0] > 255) bad();
    return Color::Palette256(vals[0]);
  }
  if (fn == "ansi16") {
    if (parse_rgb_args(inside, vals) && vals.size() == 1) {
      if (vals[0] < 0 || vals[0] > 15) bad();
      return Color::Palette16(vals[0]);
    }
    Color c;
    if (!Color::FromName(inside, &c)) bad();
    return c;
  }
  bad();
  return Color::Default();
}

tui::BorderStyle parse_border(const std::string& raw) {
  std::string l = lower(trim(raw));
  if (l == "light") return tui::LIGHT;
  if (l == "dashed") return tui::DASHED;
  if (l == "heavy") return tui::HEAVY;
  if (l == "double") return tui::DOUBLE;
  if (l == "rounded") return tui::ROUNDED;
  if (l == "empty") return tui::EMPTY;
  throw std::runtime_error("Invalid border style: " + raw);
}

namespace {

void apply_style(Style& st, const PTree& node) {
  if (auto v = node.get_string("fgcolor")) st.fg = parse_color(*v);
  if (auto v = node.get_string("bgcolor")) st.bg = parse_color(*v);
  st.bold = node.get_bool("bold", st.bold);
  st.dim = node.get_bool("dim", st.dim);
  st.underlined = node.get_bool("underlined", st.underlined);
  st.italic = node.get_bool("italic", st.italic);
  st.inverted = node.get_bool("inverted", st.inverted);
  st.strikethrough = node.get_bool("strikethrough", st.strikethrough);
  st.blink = node.get_bool("blink", st.blink);
}

// Looks for "<name>.border" literal key or "<name>" subsection with "border" key.
void apply_border(tui::BorderStyle& bs, const PTree& theme, const std::string& name) {
  if (const PTree* lit = theme.find(name + ".border")) { bs = parse_border(lit->data); return; }
  if (const PTree* sub = theme.find(name)) {
    if (const PTree* b = sub->find("border")) bs = parse_border(b->data);
  }
}

void apply_markdown_theme(MarkdownTheme& md, const PTree* node) {
  if (!node) return;
  for (int i = 0; i < 6; ++i) {
    if (auto v = node->get_string("header" + std::to_string(i + 1))) md.header[i].fg = parse_color(*v);
  }
  if (auto v = node->get_string("list")) md.list.fg = parse_color(*v);
  if (auto v = node->get_string("quote")) md.quote.fg = parse_color(*v);
  if (auto v = node->get_string("code-fg")) md.code.fg = parse_color(*v);
  if (auto v = node->get_string("link")) md.link.fg = parse_color(*v);
}

const PTree* find_sub(const PTree* base, const std::string& name) {
  if (!base) return nullptr;
  return base->find(name);
}

}  // namespace

void apply_config_tree(Config& cfg, const PTree& tree) {
  if (auto v = tree.get_string("log-dir-path")) cfg.log_dir_path = *v;
  if (auto v = tree.get_string("log-filename-format")) cfg.log_filename_format = *v;
  if (auto v = tree.get_string("log-name-format")) cfg.log_filename_format = *v;
  cfg.sunday_start = tree.get_bool("sunday-start", cfg.sunday_start);
  cfg.first_line_section = tree.get_bool("first-line-section", cfg.first_line_section);
  if (auto v = tree.get_string("password")) cfg.password = *v;

  if (const PTree* git = tree.find("git")) {
    cfg.git.enabled = git->get_bool("enable-git-log-repo", false);
    if (auto v = git->get_string("ssh-key-path")) cfg.git.ssh_key_path = *v;
    if (auto v = git->get_string("ssh-pub-key-path")) cfg.git.ssh_pub_key_path = *v;
    if (auto v = git->get_string("repo-root")) cfg.git.repo_root = *v;
    if (auto v = git->get_string("remote-name")) cfg.git.remote_name = *v;
    if (auto v = git->get_string("main-branch-name")) cfg.git.main_branch_name = *v;
  }

  if (const PTree* ev = tree.find("calendar-events")) {
    cfg.recent_events_window = ev->get_int("recent-events-window", cfg.recent_events_window);
    for (const auto& group : ev->children) {
      if (group.second->children.empty()) continue;
      bool has_sub = false;
      for (const auto& e : group.second->children)
        if (!e.second->children.empty()) has_sub = true;
      if (!has_sub) continue;
      for (const auto& e : group.second->children) {
        if (e.second->children.empty()) continue;
        const PTree* name = e.second->find("name");
        if (!name) throw std::runtime_error("No such node (name)");
        const PTree* date = e.second->find("date");
        if (!date) throw std::runtime_error("No such node (date)");
        CalendarEvent event;
        event.name = name->data;
        std::string d = trim(date->data);
        // format DD.MM or DD.MM.
        auto parts = split(d, '.');
        if (!parts.empty() && parts.back().empty()) parts.pop_back();
        bool ok = parts.size() == 2;
        if (ok) {
          for (auto& p : parts) {
            if (p.empty()) ok = false;
            for (char c : p)
              if (!std::isdigit(static_cast<unsigned char>(c))) ok = false;
          }
        }
        if (!ok) throw std::runtime_error("Invalid date format: " + date->data);
        event.day = std::atoi(parts[0].c_str());
        event.month = std::atoi(parts[1].c_str());
        cfg.events[group.first].push_back(event);
      }
    }
  }

  const PTree* view = tree.find("view");
  const PTree* annual = find_sub(view, "annual-view");
  const PTree* theme = find_sub(annual, "theme");
  if (theme) {
    auto& t = cfg.annual_theme;
    if (const PTree* n = theme->find("log-date")) apply_style(t.log_date, *n);
    if (const PTree* n = theme->find("empty-date")) apply_style(t.empty_date, *n);
    if (const PTree* n = theme->find("highlighted-date")) apply_style(t.highlighted_date, *n);
    if (const PTree* n = theme->find("weekend-date")) apply_style(t.weekend_date, *n);
    if (const PTree* n = theme->find("event-date")) apply_style(t.event_date, *n);
    if (const PTree* n = theme->find("todays-date")) apply_style(t.todays_date, *n);
    if (auto v = theme->get_string("calendar-border")) t.calendar_border = parse_border(*v);
    if (auto v = theme->get_string("calendar-month-border")) t.calendar_month_border = parse_border(*v);
    apply_border(t.tags_menu_border, *theme, "tags-menu");
    apply_border(t.sections_menu_border, *theme, "sections-menu");
    apply_border(t.events_list_border, *theme, "events-list");
    apply_border(t.log_entry_preview_border, *theme, "log-entry-preview");
    const PTree* md = nullptr;
    if (const PTree* lit = theme->find("log-entry-preview.markdown-theme")) md = lit;
    else if (const PTree* sub = theme->find("log-entry-preview")) md = sub->find("markdown-theme");
    apply_markdown_theme(t.preview_markdown, md);
  }
  const PTree* scratch = find_sub(view, "scratchpad-view");
  const PTree* stheme = find_sub(scratch, "theme");
  if (stheme) {
    auto& t = cfg.scratchpad_theme;
    apply_border(t.menu_border, *stheme, "menu");
    apply_border(t.preview_border, *stheme, "preview");
    const PTree* md = nullptr;
    if (const PTree* lit = stheme->find("preview.markdown-theme")) md = lit;
    else if (const PTree* sub = stheme->find("preview")) md = sub->find("markdown-theme");
    apply_markdown_theme(t.preview_markdown, md);
  }
}

std::string home_dir() {
  const char* h = std::getenv("HOME");
  return h ? std::string(h) : std::string();
}

std::string default_config_path() { return home_dir() + "/.caps-log/config.ini"; }

Config load_config(const std::string& path) {
  Config cfg;
  cfg.log_dir_path = home_dir() + "/.caps-log/day";
  std::ifstream in(path);
  if (!in) throw std::runtime_error("Failed to open file: " + path);
  std::stringstream ss;
  ss << in.rdbuf();
  PTree tree;
  try {
    tree = parse_ini(ss.str());
  } catch (const ParseError& e) {
    throw std::runtime_error(std::string("Failed to parse configuration file: ") + e.what());
  }
  apply_config_tree(cfg, tree);
  return cfg;
}

