// ------------------------------------------------------------------ Date
Date Date::today() {
  std::time_t t = std::time(nullptr);
  std::tm lt{};
  localtime_r(&t, &lt);
  return Date{lt.tm_year + 1900, lt.tm_mon + 1, lt.tm_mday};
}

int Date::days_in_month(int year, int month) {
  static const int d[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
  if (month == 2) {
    bool leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    return leap ? 29 : 28;
  }
  return d[month - 1];
}

long Date::day_number() const {
  // days from civil (Howard Hinnant)
  int y = year, m = month, d = day;
  y -= m <= 2;
  const long era = (y >= 0 ? y : y - 399) / 400;
  const unsigned yoe = static_cast<unsigned>(y - era * 400);
  const unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
  const unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
  return era * 146097 + static_cast<long>(doe) - 719468;
}

Date Date::from_day_number(long z) {
  z += 719468;
  const long era = (z >= 0 ? z : z - 146096) / 146097;
  const unsigned doe = static_cast<unsigned>(z - era * 146097);
  const unsigned yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
  const long y = static_cast<long>(yoe) + era * 400;
  const unsigned doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
  const unsigned mp = (5 * doy + 2) / 153;
  const unsigned d = doy - (153 * mp + 2) / 5 + 1;
  const unsigned m = mp + (mp < 10 ? 3 : -9);
  return Date{static_cast<int>(y + (m <= 2)), static_cast<int>(m), static_cast<int>(d)};
}

int Date::weekday() const {
  long n = day_number();  // 1970-01-01 was a Thursday (index 3 with Monday=0)
  long w = (n % 7 + 7 + 3) % 7;
  return static_cast<int>(w);
}

// ------------------------------------------------------------------ parsing
namespace {
std::string trim(const std::string& s) {
  size_t a = 0, b = s.size();
  while (a < b && std::isspace(static_cast<unsigned char>(s[a]))) ++a;
  while (b > a && std::isspace(static_cast<unsigned char>(s[b - 1]))) --b;
  return s.substr(a, b - a);
}
std::string lower(std::string s) {
  for (auto& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
  return s;
}
}  // namespace

LogEntry parse_log(const Date& date, const std::string& content, bool ignore_first_line_section) {
  static const std::regex section_re(R"(^\s*#\s+(.+)$)");
  static const std::regex tag_re(R"(^\s*\*\s+([a-zA-Z0-9 \-]+)(\(.+\))?(:.*)?$)");
  LogEntry entry;
  entry.date = date;
  entry.content = content;
  std::string current = kRootSectionName;
  std::istringstream in(content);
  std::string line;
  bool first = true;
  while (std::getline(in, line)) {
    if (!line.empty() && line.back() == '\r') line.pop_back();
    std::string rtrimmed = line;
    while (!rtrimmed.empty() && std::isspace(static_cast<unsigned char>(rtrimmed.back()))) rtrimmed.pop_back();
    std::smatch m;
    bool is_first = first;
    first = false;
    if (!(is_first && ignore_first_line_section) && std::regex_match(rtrimmed, m, section_re)) {
      std::string title = lower(trim(m[1].str()));
      if (!title.empty()) {
        current = title;
        entry.sections[current];
        continue;
      }
    }
    if (std::regex_match(rtrimmed, m, tag_re)) {
      std::string tag = lower(trim(m[1].str()));
      if (!tag.empty()) {
        entry.sections[current].insert(tag);
        entry.all_tags.insert(tag);
      }
    }
  }
  return entry;
}

// ------------------------------------------------------------------ repo
LogRepository::LogRepository(std::string log_dir, std::string format, std::string password)
    : log_dir_(std::move(log_dir)), format_(std::move(format)), password_(std::move(password)) {
  while (log_dir_.size() > 1 && log_dir_.back() == '/') log_dir_.pop_back();
  encrypted_ = fs::exists(marker_path());
}

std::string LogRepository::file_name_for(const Date& d) const {
  std::tm tm{};
  tm.tm_year = d.year - 1900;
  tm.tm_mon = d.month - 1;
  tm.tm_mday = d.day;
  tm.tm_wday = (d.weekday() + 1) % 7;
  char buf[512];
  size_t n = strftime(buf, sizeof buf, format_.c_str(), &tm);
  return std::string(buf, n);
}

std::string LogRepository::path_for(const Date& d) const {
  return log_dir_ + "/y" + std::to_string(d.year) + "/" + file_name_for(d);
}

bool LogRepository::exists(const Date& d) const { return fs::is_regular_file(path_for(d)); }

std::string LogRepository::read_file(const std::string& path) const {
  std::ifstream in(path, std::ios::binary);
  std::stringstream ss;
  ss << in.rdbuf();
  std::string data = ss.str();
  if (encrypted_) return crypto::decrypt(data, password_);
  return data;
}

void LogRepository::write_file(const std::string& path, const std::string& content) const {
  fs::create_directories(fs::path(path).parent_path());
  std::ofstream out(path, std::ios::binary | std::ios::trunc);
  out << (encrypted_ ? crypto::encrypt(content, password_) : content);
}

std::optional<std::string> LogRepository::read(const Date& d) const {
  std::string p = path_for(d);
  if (!fs::is_regular_file(p)) return std::nullopt;
  return read_file(p);
}

void LogRepository::write(const Date& d, const std::string& content) const { write_file(path_for(d), content); }

void LogRepository::remove(const Date& d) const {
  std::error_code ec;
  fs::remove(path_for(d), ec);
}

std::vector<LogRepository::Scratchpad> LogRepository::scratchpads() const {
  std::vector<Scratchpad> out;
  std::error_code ec;
  fs::create_directories(scratchpad_dir(), ec);
  for (const auto& e : fs::directory_iterator(scratchpad_dir(), ec)) {
    if (!e.is_regular_file()) continue;
    Scratchpad s;
    s.name = e.path().filename().string();
    s.path = e.path().string();
    struct stat st{};
    s.mtime = (stat(s.path.c_str(), &st) == 0) ? st.st_mtime : 0;
    out.push_back(s);
  }
  return out;
}

bool LogRepository::matches_format(const std::string& filename) const {
  // Build a regex from the strftime-like format.
  std::string re;
  std::vector<char> groups;
  for (size_t i = 0; i < format_.size(); ++i) {
    char c = format_[i];
    if (c == '%' && i + 1 < format_.size()) {
      char f = format_[++i];
      switch (f) {
        case 'Y': re += "(\\d{4})"; groups.push_back('Y'); break;
        case 'y': re += "(\\d{1,2})"; groups.push_back('y'); break;
        case 'm': re += "(\\d{1,2})"; groups.push_back('m'); break;
        case 'd': re += "(\\d{1,2})"; groups.push_back('d'); break;
        case '%': re += "%"; break;
        default: re += "(\\d+)"; groups.push_back(f); break;
      }
    } else {
      static const std::string special = R"(\^$.|?*+()[]{})";
      if (special.find(c) != std::string::npos) re += '\\';
      re += c;
    }
  }
  std::regex r(re, std::regex::icase);
  std::smatch m;
  if (!std::regex_match(filename, m, r)) return false;
  for (size_t i = 0; i < groups.size(); ++i) {
    int v = std::atoi(m[i + 1].str().c_str());
    if (groups[i] == 'm' && (v < 1 || v > 12)) return false;
    if (groups[i] == 'd' && (v < 1 || v > 31)) return false;
  }
  return true;
}

std::vector<std::string> LogRepository::crypto_files() const {
  std::vector<std::string> out;
  // Throws filesystem_error if the directory cannot be opened (like the original tool).
  for (const auto& e : fs::directory_iterator(log_dir_)) {
    if (!e.is_directory()) continue;
    std::string name = e.path().filename().string();
    if (name == "scratchpads") {
      for (const auto& f : fs::directory_iterator(e.path()))
        if (f.is_regular_file()) out.push_back(f.path().string());
      continue;
    }
    if (name.size() < 2 || name[0] != 'y') continue;
    bool digits = true;
    for (size_t i = 1; i < name.size(); ++i)
      if (!std::isdigit(static_cast<unsigned char>(name[i]))) digits = false;
    if (!digits) continue;
    for (const auto& f : fs::directory_iterator(e.path())) {
      if (!f.is_regular_file()) continue;
      if (matches_format(f.path().filename().string())) out.push_back(f.path().string());
    }
  }
  std::sort(out.begin(), out.end());
  return out;
}

}  // namespace app
