struct PieceStyle {
  bool bold = false, italic = false, code = false, link = false;
};

Element make_piece(const std::string& txt, const Style* base, const PieceStyle& ps, const MarkdownTheme& theme) {
  Style st;
  if (base) st = *base;
  if (ps.bold) st.bold = true;
  if (ps.italic) st.italic = true;
  if (ps.code) { st.fg = theme.code.fg; if (theme.code.bg) st.bg = theme.code.bg; }
  if (ps.link) { st.fg = theme.link.fg; st.underlined = true; }
  return st.apply(text(txt));
}

// Parses inline markdown; appends styled pieces. `base` is the style of the whole line (headers).
void parse_inline(const std::string& s, const Style* base, const MarkdownTheme& theme, Elements& out) {
  PieceStyle ps;
  std::string buf;
  auto flush = [&]() {
    if (!buf.empty()) {
      out.push_back(make_piece(buf, base, ps, theme));
      buf.clear();
    }
  };
  auto marker = [&](const std::string& m) {
    flush();
    PieceStyle plain;
    out.push_back(make_piece(m, base, plain, theme));
  };
  size_t i = 0;
  while (i < s.size()) {
    char c = s[i];
    if (c == '`') {
      size_t close = s.find('`', i + 1);
      if (close != std::string::npos) {
        marker("`");
        std::string code = s.substr(i + 1, close - i - 1);
        PieceStyle cs = ps;
        cs.code = true;
        if (!code.empty()) out.push_back(make_piece(code, base, cs, theme));
        marker("`");
        i = close + 1;
        continue;
      }
      buf += c;
      ++i;
      continue;
    }
    if ((c == '*' || c == '_')) {
      if (i + 1 < s.size() && s[i + 1] == c) {
        marker(std::string(2, c));
        ps.bold = !ps.bold;
        i += 2;
        continue;
      }
      marker(std::string(1, c));
      ps.italic = !ps.italic;
      ++i;
      continue;
    }
    if (s.compare(i, 7, "http://") == 0 || s.compare(i, 8, "https://") == 0) {
      size_t end = i;
      while (end < s.size() && !std::isspace(static_cast<unsigned char>(s[end]))) ++end;
      flush();
      PieceStyle ls = ps;
      ls.link = true;
      out.push_back(make_piece(s.substr(i, end - i), base, ls, theme));
      i = end;
      continue;
    }
    buf += c;
    ++i;
  }
  flush();
}

std::string rtrim(const std::string& s) {
  std::string r = s;
  while (!r.empty() && std::isspace(static_cast<unsigned char>(r.back()))) r.pop_back();
  return r;
}

}  // namespace

std::vector<Element> render_markdown(const std::string& content, const MarkdownTheme& theme) {
  static const std::regex header_re(R"(^(#+) (.*)$)");
  static const std::regex list_re(R"(^(\s*)([*+-]|\d+\.) (.*)$)");
  static const std::regex quote_re(R"(^(\s*)(> ?)(.*)$)");
  static const std::regex hr_re(R"(^\s*-{3,}\s*$)");
  std::vector<Element> out;
  bool in_code = false;
  for (const std::string& raw : split_lines(content)) {
    std::string line = raw;
    std::string rt = rtrim(line);
    if (rt.rfind("```", 0) == 0 || rt.rfind("~~~", 0) == 0) {
      in_code = !in_code;
      out.push_back(theme.code.apply(text(line)));
      continue;
    }
    if (in_code) {
      out.push_back(theme.code.apply(text(line)));
      continue;
    }
    std::smatch m;
    if (std::regex_match(line, m, header_re)) {
      int level = static_cast<int>(m[1].length());
      if (level > 6) level = 6;
      const Style& st = theme.header[level - 1];
      Elements pieces;
      parse_inline(line, &st, theme, pieces);
      pieces.push_back(st.apply(filler()));
      out.push_back(hbox(std::move(pieces)));
      continue;
    }
    if (std::regex_match(rt, hr_re)) {
      out.push_back(theme.hr.apply(text(line)));
      continue;
    }
    if (std::regex_match(line, m, list_re)) {
      Elements pieces;
      if (m[1].length() > 0) pieces.push_back(text(m[1].str()));
      pieces.push_back(theme.list.apply(text(m[2].str() + " ")));
      parse_inline(m[3].str(), nullptr, theme, pieces);
      out.push_back(hbox(std::move(pieces)));
      continue;
    }
    if (std::regex_match(line, m, quote_re)) {
      Elements pieces;
      if (m[1].length() > 0) pieces.push_back(text(m[1].str()));
      pieces.push_back(theme.quote.apply(text(m[2].str())));
      parse_inline(m[3].str(), nullptr, theme, pieces);
      out.push_back(hbox(std::move(pieces)));
      continue;
    }
    Elements pieces;
    parse_inline(line, nullptr, theme, pieces);
    if (pieces.empty()) out.push_back(text(""));
    else out.push_back(hbox(std::move(pieces)));
  }
  return out;
}

}  // namespace app
