    }
    element = element | reflect(boxes_[i]);
    if (focused_entry == i) element = is_menu_focused ? focus(element) : select(element);
    elements.push_back(element);
  }
  return vbox(std::move(elements)) | reflect(box_);
}

bool Menu::OnEvent(const Event& event) {
  Clamp();
  if (event.type == Event::Mouse) {
    if (event.mouse_button == 0 && event.mouse_press) {
      for (int i = 0; i < size(); ++i) {
        if (boxes_[i].Contain(event.mouse_x, event.mouse_y)) {
          if (parent_) parent_->SetActiveChild(this);
          focused_entry = i;
          if (*selected_ != i) {
            *selected_ = i;
            if (option_.on_change) option_.on_change();
          }
          return true;
        }
      }
    }
    return false;
  }
  if (Focused()) {
    const int old_selected = *selected_;
    if (event == events::ArrowUp || event.is_char("k")) (*selected_)--;
    if (event == events::ArrowDown || event.is_char("j")) (*selected_)++;
    if (event == events::PageUp) *selected_ -= box_.y_max - box_.y_min;
    if (event == events::PageDown) *selected_ += box_.y_max - box_.y_min;
    if (event == events::Home) *selected_ = 0;
    if (event == events::End) *selected_ = size() - 1;
    if (event == events::Tab && size()) *selected_ = (*selected_ + 1) % size();
    if (event == events::TabReverse && size()) *selected_ = (*selected_ + size() - 1) % size();
    *selected_ = std::clamp(*selected_, 0, std::max(0, size() - 1));
    if (*selected_ != old_selected) {
      focused_entry = *selected_;
      if (option_.on_change) option_.on_change();
      return true;
    }
  }
  if (event == events::Return) {
    if (option_.on_enter) option_.on_enter();
    return true;
  }
  return false;
}

// ------------------------------------------------------------------ Input
Input::Input(std::string* content, InputOption option) : content_(content), option_(std::move(option)) {}

static std::string PasswordText(const std::string& s, bool password) {
  if (!password) return s;
  std::string out;
  for (size_t i = 0; i < utf8_glyphs(s).size(); ++i) out += "•";
  return out;
}

Element Input::Render() {
  const bool is_focused = Focused();
  auto focused_dec = [&](Element e) { return is_focused ? focus(std::move(e)) : select(std::move(e)); };
  auto transform = [&](Element e, bool is_placeholder) {
    e = e | color(Color::Palette16(Color::White));
    if (is_placeholder) e = dim(e);
    if (is_focused) e = inverted(e);
    return e;
  };
  if (content_->empty()) {
    Element element = text(option_.placeholder) | xflex | frame;
    if (is_focused) element = focus(element);
    return transform(element, true) | reflect(box_);
  }
  cursor_position = std::clamp(cursor_position, 0, static_cast<int>(content_->size()));
  const std::string& line = *content_;
  Element element;
  if (cursor_position >= static_cast<int>(line.size())) {
    element = hbox({text(PasswordText(line, option_.password)), focused_dec(text(" "))}) | xflex;
  } else {
    // find glyph boundaries
    int start = cursor_position;
    int end = start + 1;
    while (end < static_cast<int>(line.size()) && (static_cast<unsigned char>(line[end]) & 0xC0) == 0x80) ++end;
    element = hbox({text(PasswordText(line.substr(0, start), option_.password)),
                    focused_dec(text(PasswordText(line.substr(start, end - start), option_.password))),
                    text(PasswordText(line.substr(end), option_.password))}) |
              xflex;
  }
  element = vbox({element}) | frame;
  return transform(element, false) | xflex | reflect(box_);
}

bool Input::OnEvent(const Event& event) {
  cursor_position = std::clamp(cursor_position, 0, static_cast<int>(content_->size()));
  if (event == events::Return) {
    if (option_.on_enter) option_.on_enter();
    return true;
  }
  if (event.type == Event::Mouse) return false;
  if (!Focused()) return false;
  auto prev_glyph = [&](int pos) {
    if (pos <= 0) return 0;
    int p = pos - 1;
    while (p > 0 && (static_cast<unsigned char>((*content_)[p]) & 0xC0) == 0x80) --p;
    return p;
  };
  auto next_glyph = [&](int pos) {
    int n = static_cast<int>(content_->size());
    if (pos >= n) return n;
    int p = pos + 1;
    while (p < n && (static_cast<unsigned char>((*content_)[p]) & 0xC0) == 0x80) ++p;
    return p;
  };
  if (event == events::Backspace) {
    if (cursor_position == 0) return false;
    int start = prev_glyph(cursor_position);
    content_->erase(start, cursor_position - start);
    cursor_position = start;
    if (option_.on_change) option_.on_change();
    return true;
  }
  if (event == events::Delete) {
    if (cursor_position >= static_cast<int>(content_->size())) return false;
    int end = next_glyph(cursor_position);
    content_->erase(cursor_position, end - cursor_position);
    if (option_.on_change) option_.on_change();
    return true;
  }
  if (event == events::ArrowLeft) {
    if (cursor_position == 0) return false;
    cursor_position = prev_glyph(cursor_position);
    return true;
  }
  if (event == events::ArrowRight) {
    if (cursor_position >= static_cast<int>(content_->size())) return false;
    cursor_position = next_glyph(cursor_position);
    return true;
  }
  if (event == events::Home) { cursor_position = 0; return true; }
  if (event == events::End) { cursor_position = static_cast<int>(content_->size()); return true; }
  if (event == events::ArrowUp || event == events::ArrowDown) return false;
  if (event.is_character()) {
    content_->insert(cursor_position, event.input);
    cursor_position += static_cast<int>(event.input.size());
    if (option_.on_change) option_.on_change();
    return true;
  }
  return false;
}

// ------------------------------------------------------------------ Button
Button::Button(std::string label, std::function<void()> on_click) : label_(std::move(label)), on_click_(std::move(on_click)) {}

Element Button::Render() {
  Element e = borderStyled(LIGHT, text(label_));
  if (Focused()) e = inverted(e);
  return e | reflect(box_);
}

bool Button::OnEvent(const Event& event) {
  if (event.type == Event::Mouse) {
    if (event.mouse_button == 0 && event.mouse_press && box_.Contain(event.mouse_x, event.mouse_y)) {
      if (parent_) parent_->SetActiveChild(this);
      if (on_click_) on_click_();
      return true;
    }
    return false;
  }
  if (event == events::Return) {
    if (on_click_) on_click_();
    return true;
  }
  return false;
}

// ------------------------------------------------------------------ Container
Container::Container(Direction d, std::vector<Component> children, int* selector) : direction_(d), selector_(selector) {
  for (auto& c : children) Add(std::move(c));
}

Element Container::Render() {
  Elements elements;
  if (direction_ == Tab) {
    ComponentBase* active = ActiveChild();
    return active ? active->Render() : text("Empty container");
  }
  for (auto& c : children_) elements.push_back(c->Render());
  if (direction_ == Vertical) return vbox(std::move(elements)) | reflect(box_);
  return hbox(std::move(elements)) | reflect(box_);
}

ComponentBase* Container::ActiveChild() {
  if (children_.empty()) return nullptr;
  int s = selector();
  if (s < 0) s = 0;
  return children_[s % children_.size()].get();
}

void Container::SetActiveChild(ComponentBase* child) {
  for (size_t i = 0; i < children_.size(); ++i)
    if (children_[i].get() == child) { selector() = static_cast<int>(i); return; }
}

void Container::MoveSelector(int dir) {
  for (int i = selector() + dir; i >= 0 && i < static_cast<int>(children_.size()); i += dir) {
    if (children_[i]->Focusable()) { selector() = i; return; }
  }
}

void Container::MoveSelectorWrap(int dir) {
  if (children_.empty()) return;
  int n = static_cast<int>(children_.size());
  for (int offset = 1; offset < n; ++offset) {
    int i = ((selector() + offset * dir) % n + n) % n;
    if (children_[i]->Focusable()) { selector() = i; return; }
  }
}

bool Container::OnEvent(const Event& event) {
  if (event.type == Event::Mouse) {
    for (auto& child : children_)
      if (child->OnEvent(event)) return true;
    return false;
  }
  if (!Focused()) return false;
  ComponentBase* active = ActiveChild();
  if (active && active->OnEvent(event)) return true;
  return EventHandler(event);
}

bool Container::EventHandler(const Event& event) {
  if (direction_ == Tab) return false;
  const int old_selected = selector();
  if (direction_ == Vertical) {
    if (event == events::ArrowUp || event.is_char("k")) MoveSelector(-1);
    if (event == events::ArrowDown || event.is_char("j")) MoveSelector(+1);
    if (event == events::PageUp) for (int i = 0; i < box_.y_max - box_.y_min; ++i) MoveSelector(-1);
    if (event == events::PageDown) for (int i = 0; i < box_.y_max - box_.y_min; ++i) MoveSelector(+1);
    if (event == events::Home) for (size_t i = 0; i < children_.size(); ++i) MoveSelector(-1);
    if (event == events::End) for (size_t i = 0; i < children_.size(); ++i) MoveSelector(+1);
  } else {
    if (event == events::ArrowLeft || event.is_char("h")) MoveSelector(-1);
    if (event == events::ArrowRight || event.is_char("l")) MoveSelector(+1);
  }
  if (event == events::Tab) MoveSelectorWrap(+1);
  if (event == events::TabReverse) MoveSelectorWrap(-1);
  selector() = std::max(0, std::min(static_cast<int>(children_.size()) - 1, selector()));
  return old_selected != selector();
}

