// ------------------------------------------------------------------ data

void App::load_year() {
  logs_.clear();
  for (int m = 1; m <= 12; ++m) {
    for (int d = 1; d <= Date::days_in_month(year_, m); ++d) {
      Date date{year_, m, d};
      auto content = repo_.read(date);
      if (!content) continue;
      logs_[date] = parse_log(date, *content, !cfg_.first_line_section);
    }
  }
  rebuild_menus();
}

void App::rebuild_menus() {
  // sections
  std::map<std::string, int> section_counts;
  for (const auto& [date, entry] : logs_)
    for (const auto& [sec, tags] : entry.sections) section_counts[sec]++;
  section_names_.clear();
  section_entries_.clear();
  section_entries_.push_back("<select none>");
  for (const auto& [name, count] : section_counts) {
    section_names_.push_back(name);
    section_entries_.push_back(format_entry(count, name));
  }
  if (section_selected_ >= static_cast<int>(section_entries_.size())) section_selected_ = 0;
  // tags (filtered by section)
  std::map<std::string, int> tag_counts;
  std::string section_filter = section_selected_ > 0 ? section_names_[section_selected_ - 1] : "";
  for (const auto& [date, entry] : logs_) {
    std::set<std::string> tags;
    if (section_filter.empty()) {
      tags = entry.all_tags;
    } else {
      auto it = entry.sections.find(section_filter);
      if (it != entry.sections.end()) tags = it->second;
    }
    for (const auto& t : tags) tag_counts[t]++;
  }
  tag_names_.clear();
  tag_entries_.clear();
  tag_entries_.push_back("<select none>");
  for (const auto& [name, count] : tag_counts) {
    tag_names_.push_back(name);
    tag_entries_.push_back(format_entry(count, name));
  }
  if (tag_selected_ >= static_cast<int>(tag_entries_.size())) tag_selected_ = 0;
  rebuild_highlights();
}

void App::rebuild_highlights() {
  highlighted_.clear();
  std::string section = section_selected_ > 0 && section_selected_ - 1 < static_cast<int>(section_names_.size())
                            ? section_names_[section_selected_ - 1]
                            : "";
  std::string tag = tag_selected_ > 0 && tag_selected_ - 1 < static_cast<int>(tag_names_.size())
                        ? tag_names_[tag_selected_ - 1]
                        : "";
  if (section.empty() && tag.empty()) return;
  for (const auto& [date, entry] : logs_) {
    bool match = false;
    if (!section.empty()) {
      auto it = entry.sections.find(section);
      if (it != entry.sections.end()) {
        match = tag.empty() || it->second.count(tag) > 0;
      }
    } else {
      match = entry.all_tags.count(tag) > 0;
    }
    if (match) highlighted_.insert(date);
  }
}

void App::reload_scratchpads() {
  scratchpads_ = repo_.scratchpads();
  scratch_entries_.clear();
  std::string make_new = "Make new scratchpad";
  make_new.resize(35, ' ');
  scratch_entries_.push_back(make_new);
  for (const auto& s : scratchpads_) {
    std::string name = s.name;
    if (string_width(name) > 32) {
      // keep first 29 glyphs
      auto glyphs = utf8_glyphs(name);
      std::string cut;
      int w = 0;
      for (const auto& g : glyphs) {
        int gw = string_width(g);
        if (w + gw > 29) break;
        cut += g;
        w += gw;
      }
      name = cut + "...";
    }
    int w = string_width(name);
    if (w < 32) name += std::string(32 - w, ' ');
    char datebuf[32];
    std::tm tm{};
    localtime_r(&s.mtime, &tm);
    strftime(datebuf, sizeof datebuf, "%y-%m-%d", &tm);
    scratch_entries_.push_back(name + " " + datebuf);
  }
  if (scratch_selected_ >= static_cast<int>(scratch_entries_.size())) scratch_selected_ = 0;
}

std::vector<std::pair<std::string, CalendarEvent>> App::events_on(int month, int day) const {
  std::vector<std::pair<std::string, CalendarEvent>> out;
  for (const auto& [group, events] : cfg_.events) {
    std::vector<CalendarEvent> sorted = events;
    std::sort(sorted.begin(), sorted.end(), [](const CalendarEvent& a, const CalendarEvent& b) { return a.name < b.name; });
    for (const auto& e : sorted)
      if (e.month == month && e.day == day) out.emplace_back(group, e);
  }
  return out;
}

std::string App::today_event_string() const {
  auto evs = events_on(today_.month, today_.day);
  if (evs.empty()) return "";
  return evs.back().first + " - " + evs.back().second.name;
}

std::string App::selected_event_string() const {
  auto evs = events_on(selected_.month, selected_.day);
  if (evs.empty()) return "";
  std::string out = " - ";
  std::string current_group;
  bool first_group = true;
  bool first_in_group = true;
  for (const auto& [group, e] : evs) {
    if (group != current_group) {
      if (!first_group) out += "; ";
      out += group + ": ";
      current_group = group;
      first_group = false;
      first_in_group = true;
    }
    if (!first_in_group) out += ", ";
    out += e.name;
    first_in_group = false;
  }
  return out;
}

// ------------------------------------------------------------------ components

void App::build_components() {
  MenuOption sec_opt;
  sec_opt.on_change = [this] {
    tag_selected_ = 0;
    if (tags_menu_) tags_menu_->focused_entry = 0;
    rebuild_menus();
  };
  sections_menu_ = std::make_shared<Menu>(&section_entries_, &section_selected_, sec_opt);
  MenuOption tag_opt;
  tag_opt.on_change = [this] { rebuild_highlights(); };
  tags_menu_ = std::make_shared<Menu>(&tag_entries_, &tag_selected_, tag_opt);
  calendar_comp_ = std::make_shared<CallbackComponent>([this] { return text(""); }, [this](const Event& e) { return on_calendar_event(e); });
  preview_comp_ = std::make_shared<CallbackComponent>([this] { return text(""); }, [this](const Event& e) { return on_preview_event(e); });
  annual_container_ = std::make_shared<IndexedContainer>([this] { return annual_focus_; });
  annual_container_->Add(sections_menu_);
  annual_container_->Add(tags_menu_);
  annual_container_->Add(calendar_comp_);
  annual_container_->Add(preview_comp_);

  MenuOption scratch_opt;
  scratch_opt.on_enter = [this] {
    if (scratch_selected_ == 0) {
      input_text_.clear();
      input_->cursor_position = 0;
      modal_title_ = "Enter the name of the scratchpad to open:";
      show_modal(Modal::ScratchName);
    } else if (scratch_selected_ - 1 < static_cast<int>(scratchpads_.size())) {
      open_scratchpad_editor(scratchpads_[scratch_selected_ - 1].path);
    }
  };
  scratch_menu_ = std::make_shared<Menu>(&scratch_entries_, &scratch_selected_, scratch_opt);
  scratch_container_ = std::make_shared<Container>(Container::Vertical, std::vector<Component>{scratch_menu_});

  view_container_ = std::make_shared<IndexedContainer>([this] { return view_ == View::Annual ? 0 : 1; });
  view_container_->Add(annual_container_);
  view_container_->Add(scratch_container_);

  InputOption in_opt;
  in_opt.on_enter = [this] {
    if (modal_ == Modal::Password) submit_password();
    else submit_scratch_name();
  };
  input_ = std::make_shared<Input>(&input_text_, in_opt);
  submit_button_ = std::make_shared<Button>("Submit", [this] {
    if (modal_ == Modal::Password) submit_password();
    else submit_scratch_name();
  });
  password_modal_ = std::make_shared<Container>(Container::Vertical, std::vector<Component>{input_, submit_button_});
  name_modal_ = password_modal_;

  yes_button_ = std::make_shared<Button>("Yes", [this] {
    if (modal_ == Modal::DeleteLog) {
      delete_selected_log();
    } else if (modal_ == Modal::ScratchDelete) {
      std::error_code ec;
      fs::remove(delete_target_, ec);
      scratch_selected_ = 0;
      scratch_menu_->focused_entry = 0;
      reload_scratchpads();
    }
    close_modal();
  });
  no_button_ = std::make_shared<Button>("No", [this] { close_modal(); });
  delete_modal_ = std::make_shared<Container>(Container::Horizontal, std::vector<Component>{yes_button_, no_button_});
  scratch_delete_modal_ = delete_modal_;

  close_button_ = std::make_shared<Button>("Close", [this] { close_modal(); });
  help_modal_ = std::make_shared<Container>(Container::Vertical, std::vector<Component>{close_button_});
  ok_button_ = std::make_shared<Button>("Ok", [this] { close_modal(); });
  git_error_modal_ = std::make_shared<Container>(Container::Vertical, std::vector<Component>{ok_button_});

  modal_container_ = std::make_shared<IndexedContainer>([this] {
    switch (modal_) {
      case Modal::Password: return 0;
      case Modal::ScratchName: case Modal::ScratchRename: return 0;
      case Modal::DeleteLog: case Modal::ScratchDelete: return 1;
      case Modal::Help: return 2;
      case Modal::GitError: return 3;
      default: return -1;
    }
  });
  modal_container_->Add(password_modal_);
  modal_container_->Add(delete_modal_);
  modal_container_->Add(help_modal_);
  modal_container_->Add(git_error_modal_);

  root_ = std::make_shared<IndexedContainer>([this] { return modal_ == Modal::None ? 0 : 1; });
  root_->Add(view_container_);
  root_->Add(modal_container_);
}

void App::show_modal(Modal m) { modal_ = m; }
void App::close_modal() { modal_ = Modal::None; }

// ------------------------------------------------------------------ rendering

Element App::render_month(int month, bool focused) {
  const AnnualViewTheme& th = cfg_.annual_theme;
  int days = Date::days_in_month(year_, month);
  Date first{year_, month, 1};
  int wd = first.weekday();  // 0 = Monday
  int iso = wd + 1;          // 1 = Monday .. 7 = Sunday
  int offset = cfg_.sunday_start ? iso : iso - 1;
  int cells = offset + days;
  int rows = (cells + 6) / 7;
  Elements lines;
  lines.push_back(underlined(text(cfg_.sunday_start ? " S  M  T  W  T  F  S " : " M  T  W  T  F  S  S ")));
  int day = 1;
  for (int r = 0; r < rows; ++r) {
    Elements row;
    for (int c = 0; c < 7; ++c) {
      int idx = r * 7 + c;
      if (idx < offset || day > days) {
        row.push_back(text("   "));
        continue;
      }
      Date date{year_, month, day};
      bool weekend;
      if (cfg_.sunday_start) weekend = (c == 0 || c == 6);
      else weekend = (c >= 5);
      bool has_log = logs_.count(date) > 0;
      bool is_today = (date == today_);
      bool highlighted = highlighted_.count(date) > 0;
      bool has_event = !events_on(month, day).empty();
      bool is_selected = (date == selected_);
      Element num = text(std::to_string(day));
      if (has_event) num = th.event_date.apply(num);
      num = has_log ? th.log_date.apply(num) : th.empty_date.apply(num);
      if (weekend) num = th.weekend_date.apply(num);
      if (highlighted) num = th.highlighted_date.apply(num);
      if (is_today) num = th.todays_date.apply(num);
      if (is_selected && focused) num = inverted(num);
      if (is_selected) num = focused ? focus(num) : select(num);
      Elements cell;
      if (day < 10) cell.push_back(text(" "));
      cell.push_back(num);
      cell.push_back(text(" "));
      row.push_back(hbox(std::move(cell)));
      ++day;
    }
    lines.push_back(hbox(std::move(row)));
  }
  return window(text(kMonthNames[month - 1]), vbox(std::move(lines)), th.calendar_month_border);
}

Element App::render_calendar(bool focused) {
  int per_row = std::clamp(term_w_ / 34, 1, 4);
  Elements rows;
  Elements current;
  for (int m = 1; m <= 12; ++m) {
    current.push_back(render_month(m, focused));
    if (static_cast<int>(current.size()) == per_row) {
      rows.push_back(hbox(std::move(current)));
      current.clear();
    }
  }
  if (!current.empty()) rows.push_back(hbox(std::move(current)));
  Element cal = window(text(std::to_string(year_)), vbox(std::move(rows)) | frame, cfg_.annual_theme.calendar_border);
  cal = flex_shrink(cal);
  if (!focused) cal = dim(cal);
  return cal;
}

Element App::render_events_window() {
  struct Item { std::string group; CalendarEvent ev; long diff; };
  std::vector<Item> items;
  long today_n = today_.day_number();
  for (const auto& [group, events] : cfg_.events) {
    std::vector<CalendarEvent> sorted = events;
    std::sort(sorted.begin(), sorted.end(), [](const CalendarEvent& a, const CalendarEvent& b) { return a.name < b.name; });
    for (const auto& e : sorted) {
      Date d{today_.year, e.month, e.day};
      long diff = d.day_number() - today_n;
      if (std::labs(diff) <= cfg_.recent_events_window) items.push_back({group, e, diff});
    }
  }
  Elements lines;
  std::string current_group;
  for (const auto& it : items) {
    if (it.group != current_group) {
      current_group = it.group;
      lines.push_back(underlined(bold(text(current_group))));
    }
    std::string when;
    if (it.diff == 0) when = "today";
    else if (it.diff > 0) when = "in " + std::to_string(it.diff) + " days";
    else when = std::to_string(-it.diff) + " days ago";
    lines.push_back(text(" - " + it.ev.name + " " + pad2(it.ev.month) + "." + pad2(it.ev.day) + ". (" + when + ")"));
  }
  Element content = vbox(std::move(lines)) | vscroll_indicator | frame;
  Element win = window(text("Recent & upcoming events (" + std::to_string(items.size()) + ")"), content,
                       cfg_.annual_theme.events_list_border);
  win = win | size(HEIGHT, LESS_THAN, 10);
  return dim(flex_shrink(win));
}

Element App::render_preview(bool focused) {
  Elements lines;
  if (!loaded_) {
    lines.push_back(text("log preview"));
  } else {
    std::string title = "log preview for " + pad2(selected_.day) + ". " + pad2(selected_.month) + ". " +
                        pad2(selected_.year % 100) + ". " + selected_event_string();
    lines.push_back(bold(hcenter(underlined(text(title)))));
    auto it = logs_.find(selected_);
    if (it != logs_.end()) {
      std::vector<Element> md = render_markdown(it->second.content, cfg_.annual_theme.preview_markdown);
      int scroll = std::clamp(preview_scroll_, 0, std::max(0, static_cast<int>(md.size()) - 1));
      for (int i = scroll; i < static_cast<int>(md.size()) && static_cast<int>(lines.size()) < 12; ++i) lines.push_back(md[i]);
    }
  }
  while (lines.size() < 12) lines.push_back(text(""));
  Element win = borderStyled(cfg_.annual_theme.log_entry_preview_border, vbox(std::move(lines)));
  win = flex_shrink(win);
  if (!focused) win = dim(win);
  return win;
}

Element App::render_annual() {
  bool main_focused = (modal_ == Modal::None);
  std::string title = "Today is: " + pad2(today_.day) + ". " + pad2(today_.month) + ". " + std::to_string(today_.year) +
                      ". " + today_event_string() + " | There are " + std::to_string(logs_.size()) +
                      " log entries for year " + std::to_string(year_) + ".";
  Element title_el = hcenter(underlined(bold(text(title))));

  Element sections = window(text("Sections"), sections_menu_->Render() | vscroll_indicator | frame,
                            cfg_.annual_theme.sections_menu_border);
  sections = sections | size(WIDTH, EQUAL, 25) | size(HEIGHT, EQUAL, 20);
  sections = flex_shrink(sections);
  if (!(main_focused && annual_focus_ == 0)) sections = dim(sections);
  Element tags = window(text("Tags"), tags_menu_->Render() | vscroll_indicator | frame, cfg_.annual_theme.tags_menu_border);
  tags = tags | size(WIDTH, EQUAL, 25) | size(HEIGHT, EQUAL, 20);
  tags = flex_shrink(tags);
  if (!(main_focused && annual_focus_ == 1)) tags = dim(tags);

  Element left = vbox({hbox({sections, tags}), render_events_window()});
  left = flex_shrink(left);
  Element cal = render_calendar(main_focused && annual_focus_ == 2);
  Element row = hbox({left, cal, text(" ")});
  Element preview = render_preview(main_focused && annual_focus_ == 3);
  Element help = dim(text("hjkl/arrow keys - navigation | d - delete log | s - see scratchpads | tab - move focus between menus and calendar"));
  Element content = vbox({title_el, yflex_shrink(hcenter(row)), preview, yflex_shrink(hcenter(help))});
  return center(content);
}

Element App::render_scratchpad() {
  bool main_focused = (modal_ == Modal::None);
  Element title = hcenter(bold(text("Scratchpad Manager")));
  Element menu_win = window(text("Scratchpads"), hbox({scratch_menu_->Render()}), cfg_.scratchpad_theme.menu_border);
  menu_win = menu_win | size(WIDTH, GREATER_THAN, 40) | size(HEIGHT, EQUAL, 24);
  if (!main_focused) menu_win = dim(menu_win);
  Elements lines;
  if (scratch_selected_ == 0 || scratch_selected_ - 1 >= static_cast<int>(scratchpads_.size())) {
    lines.push_back(bold(hcenter(underlined(text("Select a scratchpad")))));
    lines.push_back(text("No scratchpad selected"));
  } else {
    const auto& sp = scratchpads_[scratch_selected_ - 1];
    lines.push_back(bold(hcenter(underlined(text(sp.name)))));
    std::string content = repo_.read_file(sp.path);
    for (auto& e : render_markdown(content, cfg_.scratchpad_theme.preview_markdown)) {
      if (lines.size() >= 22) break;
      lines.push_back(e);
    }
  }
  Element preview = borderStyled(cfg_.scratchpad_theme.preview_border, vbox(std::move(lines)));
  preview = preview | size(WIDTH, EQUAL, term_w_ * 3 / 4);
  preview = xflex_shrink(preview);
  preview = dim(preview);
  Element content = vbox({title, separator(), hbox({menu_win, preview}), hcenter(text("Press F1 for help."))});
  return vbox({filler(), yflex_grow(hcenter(content)), filler()});
}

Element App::render_modal() {
  switch (modal_) {
    case Modal::Password:
    case Modal::ScratchName:
    case Modal::ScratchRename: {
      std::string title = modal_ == Modal::Password ? "Enter password for log files:" : modal_title_;
      Element body = vbox({separator(), hcenter(vbox({input_->Render(), submit_button_->Render()}))});
      return window(text(title), body);
    }
    case Modal::DeleteLog:
    case Modal::ScratchDelete: {
      std::string title = modal_ == Modal::DeleteLog ? "Are you sure you want to delete a log file?"
                                                     : "Are you sure you want to delete the scratchpad \"" + delete_target_ + "\"?";
      Element body = vbox({separator(), hcenter(hbox({yes_button_->Render(), no_button_->Render()}))});
      return window(text(title), body);
    }
    case Modal::Help: {
      Elements lines;
      MarkdownTheme theme;
      std::string help = kHelpText;
      // split keeping the trailing empty line
      std::vector<std::string> raw;
      std::string cur;
      for (char c : help) {
        if (c == '\n') { raw.push_back(cur); cur.clear(); }
        else cur += c;
      }
      std::string joined;
      for (auto& l : raw) joined += l + "\n";
      auto md = render_markdown(joined, theme);
      for (auto& e : md) lines.push_back(e);
      if (!raw.empty() && raw.back().empty()) lines.push_back(text(""));
      lines.push_back(separator());
      lines.push_back(hcenter(close_button_->Render()));
      return border(vbox(std::move(lines)));
    }
    case Modal::GitError: {
      Element body = vbox({separator(), hcenter(ok_button_->Render())});
      return window(text(git_error_), body);
    }
    default:
      return text("");
  }
}

Element App::render() {
  Element main = view_ == View::Annual ? render_annual() : render_scratchpad();
  if (modal_ == Modal::None) return main;
  Element bg = std::make_shared<ModalBackground>(main);
  return dbox({bg, center(clear_under(render_modal()))});
}

// ------------------------------------------------------------------ events

void App::set_year(int y) {
  year_ = y;
  selected_.year = y;
  int dim = Date::days_in_month(y, selected_.month);
  if (selected_.day > dim) selected_.day = dim;
  preview_scroll_ = 0;
  load_year();
}

void App::move_selection(int delta_days, int month_dir) {
  int dim = Date::days_in_month(selected_.year, selected_.month);
  int nd = selected_.day + delta_days;
  if (nd >= 1 && nd <= dim) {
    selected_.day = nd;
  } else {
    int nm = selected_.month + month_dir;
    if (nm < 1 || nm > 12) return;
    remembered_day_[selected_.month] = selected_.day;
    selected_.month = nm;
    int rd = remembered_day_[nm];
    if (rd < 1) rd = 1;
    rd = std::min(rd, Date::days_in_month(selected_.year, nm));
    selected_.day = rd;
  }
  remembered_day_[selected_.month] = selected_.day;
  preview_scroll_ = 0;
}

bool App::on_calendar_event(const Event& e) {
  if (e == events::ArrowLeft || e.is_char("h")) { move_selection(-1, -1); return true; }
  if (e == events::ArrowRight || e.is_char("l")) { move_selection(1, 1); return true; }
  if (e == events::ArrowUp || e.is_char("k")) { move_selection(-7, -1); return true; }
  if (e == events::ArrowDown || e.is_char("j")) { move_selection(7, 1); return true; }
  if (e == events::Return) { open_log_editor(selected_); return true; }
  return false;
}

bool App::on_preview_event(const Event& e) {
  auto it = logs_.find(selected_);
  int n = it == logs_.end() ? 0 : static_cast<int>(split_lines(it->second.content).size());
  if (e == events::ArrowDown || e.is_char("j")) { preview_scroll_ = std::clamp(preview_scroll_ + 1, 0, std::max(0, n - 1)); return true; }
  if (e == events::ArrowUp || e.is_char("k")) { preview_scroll_ = std::clamp(preview_scroll_ - 1, 0, std::max(0, n - 1)); return true; }
  return false;
}

bool App::on_annual_event(const Event& e) {
  if (e == events::Tab) { annual_focus_ = (annual_focus_ + 1) % 4; return true; }
  if (e == events::TabReverse) { annual_focus_ = (annual_focus_ + 3) % 4; return true; }
  if (view_container_->OnEvent(e)) return true;
  if (e.is_char("d")) {
    if (logs_.count(selected_)) show_modal(Modal::DeleteLog);
    return true;
  }
  if (e.is_char("s")) { view_ = View::Scratchpad; reload_scratchpads(); return true; }
  if (e.is_char("+")) { set_year(year_ + 1); return true; }
  if (e.is_char("-")) { set_year(year_ - 1); return true; }
  if (e.is_char("q") || e == events::Escape) { quit_ = true; return true; }
  if (e == events::F1) { show_modal(Modal::Help); return true; }
  return false;
}

bool App::on_scratchpad_event(const Event& e) {
  if (view_container_->OnEvent(e)) return true;
  if (e.is_char("s")) { view_ = View::Annual; return true; }
  if (e.is_char("q") || e == events::Escape) { quit_ = true; return true; }
  if (e == events::F1) { show_modal(Modal::Help); return true; }
  if (e.is_char("d")) {
    if (scratch_selected_ > 0 && scratch_selected_ - 1 < static_cast<int>(scratchpads_.size())) {
      delete_target_ = scratchpads_[scratch_selected_ - 1].name;
      show_modal(Modal::ScratchDelete);
    }
    return true;
  }
  if (e.is_char("r")) {
    if (scratch_selected_ > 0 && scratch_selected_ - 1 < static_cast<int>(scratchpads_.size())) {
      rename_target_ = scratchpads_[scratch_selected_ - 1].name;
      input_text_.clear();
      input_->cursor_position = 0;
      modal_title_ = "Enter the new name for the scratchpad \"" + rename_target_ + "\":";
      show_modal(Modal::ScratchRename);
    }
    return true;
  }
  return false;
}

bool App::on_event(const Event& e) {
  if (e == events::CtrlC) { quit_ = true; return true; }
  if (modal_ != Modal::None) {
    return modal_container_->OnEvent(e);
  }
  if (view_ == View::Annual) return on_annual_event(e);
  return on_scratchpad_event(e);
}

// ------------------------------------------------------------------ actions

void App::submit_password() {
  std::string pw = input_text_;
  LogRepository test(cfg_.log_dir_path, cfg_.log_filename_format, pw);
  std::string marker = test.read_file(test.marker_path());
  if (marker != "encryption-marker:") {
    error_message_ = "Invalid password provided!";
    exit_code_ = 1;
    quit_ = true;
    return;
  }
  cfg_.password = pw;
  repo_ = LogRepository(cfg_.log_dir_path, cfg_.log_filename_format, pw);
  close_modal();
  loaded_ = true;
  load_year();
}

static std::string ensure_md(const std::string& name) {
  if (name.size() >= 3 && name.substr(name.size() - 3) == ".md") return name;
  return name + ".md";
}

void App::submit_scratch_name() {
  std::string name = input_text_;
  if (modal_title_ == "Scratchpad name cannot be empty.") {
    close_modal();
    input_text_.clear();
    return;
  }
  if (name.empty()) {
    modal_title_ = "Scratchpad name cannot be empty.";
    view_ = View::Annual;
    return;
  }
  if (modal_ == Modal::ScratchRename) {
    std::error_code ec;
    fs::rename(repo_.scratchpad_dir() + "/" + rename_target_, repo_.scratchpad_dir() + "/" + ensure_md(name), ec);
    close_modal();
    scratch_selected_ = 0;
    scratch_menu_->focused_entry = 0;
    reload_scratchpads();
    return;
  }
  close_modal();
  std::string path = repo_.scratchpad_dir() + "/" + ensure_md(name);
  open_scratchpad_editor(path);
}

void App::delete_selected_log() {
  repo_.remove(selected_);
  preview_scroll_ = 0;
  load_year();
}

void App::run_editor_on(const std::string& path) {
  const char* editor = std::getenv("EDITOR");
  if (!editor || !*editor) return;
  term_.Uninstall();
  std::string cmd = std::string(editor) + " \"" + path + "\"";
  int r = std::system(cmd.c_str());
  (void)r;
  term_.Install();
}

void App::open_log_editor(const Date& d) {
  std::string path = repo_.path_for(d);
  if (!repo_.encrypted()) {
    std::error_code ec;
    fs::create_directories(fs::path(path).parent_path(), ec);
    run_editor_on(path);
    if (fs::is_regular_file(path, ec) && fs::file_size(path, ec) == 0) fs::remove(path, ec);
  } else {
    std::random_device rd;
    std::string tmp = "/tmp/caps-log-edit-" + std::to_string(rd() % 1000000) + ".md";
    auto existing = repo_.read(d);
    if (existing) {
      std::ofstream out(tmp, std::ios::binary);
      out << *existing;
    }
    run_editor_on(tmp);
    std::error_code ec;
    if (fs::is_regular_file(tmp, ec)) {
      std::ifstream in(tmp, std::ios::binary);
      std::stringstream ss;
      ss << in.rdbuf();
      std::string content = ss.str();
      if (content.empty()) repo_.remove(d);
      else repo_.write(d, content);
      fs::remove(tmp, ec);
    } else {
      repo_.remove(d);
    }
  }
  preview_scroll_ = 0;
  load_year();
}

void App::open_scratchpad_editor(const std::string& path) {
  std::error_code ec;
  fs::create_directories(fs::path(path).parent_path(), ec);
  if (!repo_.encrypted()) {
    run_editor_on(path);
  } else {
    std::random_device rd;
    std::string tmp = "/tmp/caps-log-edit-" + std::to_string(rd() % 1000000) + ".md";
    if (fs::is_regular_file(path, ec)) {
      std::ofstream out(tmp, std::ios::binary);
      out << repo_.read_file(path);
    }
    run_editor_on(tmp);
    if (fs::is_regular_file(tmp, ec)) {
      std::ifstream in(tmp, std::ios::binary);
      std::stringstream ss;
      ss << in.rdbuf();
      repo_.write_file(path, ss.str());
      fs::remove(tmp, ec);
    }
  }
  scratch_selected_ = 0;
  scratch_menu_->focused_entry = 0;
  reload_scratchpads();
}

// ------------------------------------------------------------------ main loop

int App::run() {
  build_components();
  for (int i = 0; i < 13; ++i) remembered_day_[i] = 1;
  remembered_day_[selected_.month] = selected_.day;
  if (prompt_password_) {
    modal_ = Modal::Password;
    input_text_.clear();
  } else {
    loaded_ = true;
    load_year();
  }
  reload_scratchpads();

  term_.Install();
  while (!quit_) {
    Terminal::Size(&term_w_, &term_h_);
    Screen screen(term_w_, term_h_);
    Element doc = render();
    Render(screen, doc);
    term_.Draw(screen);
    Event ev;
    if (!term_.NextEvent(&ev)) break;
    if (ev.type == Event::Resize) continue;
    on_event(ev);
  }
  term_.Uninstall();
  if (!error_message_.empty()) {
    std::cerr << "Captain's log encountered an error: \n " << error_message_ << std::endl;
  }
  return exit_code_;
}

}  // namespace

int run_app(const RunOptions& options) {
  App app(options);
  return app.run();
}

}  // namespace app
