// A component whose events are forwarded to a callback.
class CallbackComponent : public ComponentBase {
 public:
  CallbackComponent(std::function<Element()> render, std::function<bool(const Event&)> on_event)
      : render_(std::move(render)), on_event_(std::move(on_event)) {}
  Element Render() override { return render_(); }
  bool OnEvent(const Event& e) override { return on_event_(e); }
  bool Focusable() const override { return true; }

 private:
  std::function<Element()> render_;
  std::function<bool(const Event&)> on_event_;
};

// Container whose active child is chosen through an external index.
class IndexedContainer : public ComponentBase {
 public:
  explicit IndexedContainer(std::function<int()> index) : index_(std::move(index)) {}
  ComponentBase* ActiveChild() override {
    if (children_.empty()) return nullptr;
    int i = index_();
    if (i < 0 || i >= static_cast<int>(children_.size())) return nullptr;
    return children_[i].get();
  }
  Element Render() override { return text(""); }
  bool OnEvent(const Event& e) override {
    ComponentBase* a = ActiveChild();
    return a ? a->OnEvent(e) : false;
  }
  bool Focusable() const override { return true; }

 private:
  std::function<int()> index_;
};

class ModalBackground : public Node {
 public:
  explicit ModalBackground(Element child) : Node({std::move(child)}) {}
  void ComputeRequirement() override {
    Node::ComputeRequirement();
    requirement_ = children_[0]->requirement();
  }
  void SetBox(Box box) override {
    Node::SetBox(box);
    children_[0]->SetBox(box);
  }
  void Render(Screen& screen) override {
    Node::Render(screen);
    for (int y = box_.y_min; y <= box_.y_max; ++y)
      for (int x = box_.x_min; x <= box_.x_max; ++x) {
        Pixel& p = screen.PixelAt(x, y);
        p.dim = true;
        if (p.foreground_color == Color::Default()) p.foreground_color = Color::Palette16(Color::GrayDark);
      }
  }
};

