void App::load_year() {
  logs_.clear();
  for (int m = 1; m <= 12; ++m) {
    for (int d = 1; d <= Date::days_in_month(year_, m); ++d) {
      Date date{year_, m, d};
      auto content = repo_.read(date);
      if (!content) continue;
      logs_[date] = parse_log(date, *content, !cfg_.first_line_section);
    }
  }
  rebuild_menus();
}

void App::rebuild_menus() {
  // sections
  std::map<std::string, int> section_counts;
  for (const auto& [date, entry] : logs_)
    for (const auto& [sec, tags] : entry.sections) section_counts[sec]++;
  section_names_.clear();
  section_entries_.clear();
  section_entries_.push_back("<select none>");
  for (const auto& [name, count] : section_counts) {
    section_names_.push_back(name);
    section_entries_.push_back(format_entry(count, name));
  }
  if (section_selected_ >= static_cast<int>(section_entries_.size())) section_selected_ = 0;
  // tags (filtered by section)
  std::map<std::string, int> tag_counts;
  std::string section_filter = section_selected_ > 0 ? section_names_[section_selected_ - 1] : "";
  for (const auto& [date, entry] : logs_) {
    std::set<std::string> tags;
    if (section_filter.empty()) {
      tags = entry.all_tags;
    } else {
      auto it = entry.sections.find(section_filter);
      if (it != entry.sections.end()) tags = it->second;
    }
    for (const auto& t : tags) tag_counts[t]++;
  }
  tag_names_.clear();
  tag_entries_.clear();
  tag_entries_.push_back("<select none>");
  for (const auto& [name, count] : tag_counts) {
    tag_names_.push_back(name);
    tag_entries_.push_back(format_entry(count, name));
  }
  if (tag_selected_ >= static_cast<int>(tag_entries_.size())) tag_selected_ = 0;
  rebuild_highlights();
}

void App::rebuild_highlights() {
  highlighted_.clear();
  std::string section = section_selected_ > 0 && section_selected_ - 1 < static_cast<int>(section_names_.size())
                            ? section_names_[section_selected_ - 1]
                            : "";
  std::string tag = tag_selected_ > 0 && tag_selected_ - 1 < static_cast<int>(tag_names_.size())
                        ? tag_names_[tag_selected_ - 1]
                        : "";
  if (section.empty() && tag.empty()) return;
  for (const auto& [date, entry] : logs_) {
    bool match = false;
    if (!section.empty()) {
      auto it = entry.sections.find(section);
      if (it != entry.sections.end()) {
        match = tag.empty() || it->second.count(tag) > 0;
      }
    } else {
      match = entry.all_tags.count(tag) > 0;
    }
    if (match) highlighted_.insert(date);
  }
}

void App::reload_scratchpads() {
  scratchpads_ = repo_.scratchpads();
  scratch_entries_.clear();
  std::string make_new = "Make new scratchpad";
  make_new.resize(35, ' ');
  scratch_entries_.push_back(make_new);
  for (const auto& s : scratchpads_) {
    std::string name = s.name;
    if (string_width(name) > 32) {
      // keep first 29 glyphs
      auto glyphs = utf8_glyphs(name);
      std::string cut;
      int w = 0;
      for (const auto& g : glyphs) {
        int gw = string_width(g);
        if (w + gw > 29) break;
        cut += g;
        w += gw;
      }
      name = cut + "...";
    }
    int w = string_width(name);
    if (w < 32) name += std::string(32 - w, ' ');
    char datebuf[32];
    std::tm tm{};
    localtime_r(&s.mtime, &tm);
    strftime(datebuf, sizeof datebuf, "%y-%m-%d", &tm);
    scratch_entries_.push_back(name + " " + datebuf);
  }
  if (scratch_selected_ >= static_cast<int>(scratch_entries_.size())) scratch_selected_ = 0;
}

std::vector<std::pair<std::string, CalendarEvent>> App::events_on(int month, int day) const {
  std::vector<std::pair<std::string, CalendarEvent>> out;
  for (const auto& [group, events] : cfg_.events) {
    std::vector<CalendarEvent> sorted = events;
    std::sort(sorted.begin(), sorted.end(), [](const CalendarEvent& a, const CalendarEvent& b) { return a.name < b.name; });
    for (const auto& e : sorted)
      if (e.month == month && e.day == day) out.emplace_back(group, e);
  }
  return out;
}

std::string App::today_event_string() const {
  auto evs = events_on(today_.month, today_.day);
  if (evs.empty()) return "";
  return evs.back().first + " - " + evs.back().second.name;
}

std::string App::selected_event_string() const {
  auto evs = events_on(selected_.month, selected_.day);
  if (evs.empty()) return "";
  std::string out = " - ";
  std::string current_group;
  bool first_group = true;
  bool first_in_group = true;
  for (const auto& [group, e] : evs) {
    if (group != current_group) {
      if (!first_group) out += "; ";
      out += group + ": ";
      current_group = group;
      first_group = false;
      first_in_group = true;
    }
    if (!first_in_group) out += ", ";
    out += e.name;
    first_in_group = false;
  }
  return out;
}

