Element App::render_month(int month, bool focused) {
  const AnnualViewTheme& th = cfg_.annual_theme;
  int days = Date::days_in_month(year_, month);
  Date first{year_, month, 1};
  int wd = first.weekday();  // 0 = Monday
  int iso = wd + 1;          // 1 = Monday .. 7 = Sunday
  int offset = cfg_.sunday_start ? iso : iso - 1;
  int cells = offset + days;
  int rows = (cells + 6) / 7;
  Elements lines;
  lines.push_back(underlined(text(cfg_.sunday_start ? " S  M  T  W  T  F  S " : " M  T  W  T  F  S  S ")));
  int day = 1;
  for (int r = 0; r < rows; ++r) {
    Elements row;
    for (int c = 0; c < 7; ++c) {
      int idx = r * 7 + c;
      if (idx < offset || day > days) {
        row.push_back(text("   "));
        continue;
      }
      Date date{year_, month, day};
      bool weekend;
      if (cfg_.sunday_start) weekend = (c == 0 || c == 6);
      else weekend = (c >= 5);
      bool has_log = logs_.count(date) > 0;
      bool is_today = (date == today_);
      bool highlighted = highlighted_.count(date) > 0;
      bool has_event = !events_on(month, day).empty();
      bool is_selected = (date == selected_);
      Element num = text(std::to_string(day));
      if (has_event) num = th.event_date.apply(num);
      num = has_log ? th.log_date.apply(num) : th.empty_date.apply(num);
      if (weekend) num = th.weekend_date.apply(num);
      if (highlighted) num = th.highlighted_date.apply(num);
      if (is_today) num = th.todays_date.apply(num);
      if (is_selected && focused) num = inverted(num);
      if (is_selected) num = focused ? focus(num) : select(num);
      Elements cell;
      if (day < 10) cell.push_back(text(" "));
      cell.push_back(num);
      cell.push_back(text(" "));
      row.push_back(hbox(std::move(cell)));
      ++day;
    }
    lines.push_back(hbox(std::move(row)));
  }
  return window(text(kMonthNames[month - 1]), vbox(std::move(lines)), th.calendar_month_border);
}

Element App::render_calendar(bool focused) {
  int per_row = std::clamp(term_w_ / 34, 1, 4);
  Elements rows;
  Elements current;
  for (int m = 1; m <= 12; ++m) {
    current.push_back(render_month(m, focused));
    if (static_cast<int>(current.size()) == per_row) {
      rows.push_back(hbox(std::move(current)));
      current.clear();
    }
  }
  if (!current.empty()) rows.push_back(hbox(std::move(current)));
  Element cal = window(text(std::to_string(year_)), vbox(std::move(rows)) | frame, cfg_.annual_theme.calendar_border);
  cal = flex_shrink(cal);
  if (!focused) cal = dim(cal);
  return cal;
}

Element App::render_events_window() {
  struct Item { std::string group; CalendarEvent ev; long diff; };
  std::vector<Item> items;
  long today_n = today_.day_number();
  for (const auto& [group, events] : cfg_.events) {
    std::vector<CalendarEvent> sorted = events;
    std::sort(sorted.begin(), sorted.end(), [](const CalendarEvent& a, const CalendarEvent& b) { return a.name < b.name; });
    for (const auto& e : sorted) {
      Date d{today_.year, e.month, e.day};
      long diff = d.day_number() - today_n;
      if (std::labs(diff) <= cfg_.recent_events_window) items.push_back({group, e, diff});
    }
  }
  Elements lines;
  std::string current_group;
  for (const auto& it : items) {
    if (it.group != current_group) {
      current_group = it.group;
      lines.push_back(underlined(bold(text(current_group))));
    }
    std::string when;
    if (it.diff == 0) when = "today";
    else if (it.diff > 0) when = "in " + std::to_string(it.diff) + " days";
    else when = std::to_string(-it.diff) + " days ago";
    lines.push_back(text(" - " + it.ev.name + " " + pad2(it.ev.month) + "." + pad2(it.ev.day) + ". (" + when + ")"));
  }
  Element content = vbox(std::move(lines)) | vscroll_indicator | frame;
  Element win = window(text("Recent & upcoming events (" + std::to_string(items.size()) + ")"), content,
                       cfg_.annual_theme.events_list_border);
  win = win | size(HEIGHT, LESS_THAN, 10);
  return dim(flex_shrink(win));
}

Element App::render_preview(bool focused) {
  Elements lines;
  if (!loaded_) {
    lines.push_back(text("log preview"));
  } else {
    std::string title = "log preview for " + pad2(selected_.day) + ". " + pad2(selected_.month) + ". " +
                        pad2(selected_.year % 100) + ". " + selected_event_string();
    lines.push_back(bold(hcenter(underlined(text(title)))));
    auto it = logs_.find(selected_);
    if (it != logs_.end()) {
      std::vector<Element> md = render_markdown(it->second.content, cfg_.annual_theme.preview_markdown);
      int scroll = std::clamp(preview_scroll_, 0, std::max(0, static_cast<int>(md.size()) - 1));
      for (int i = scroll; i < static_cast<int>(md.size()) && static_cast<int>(lines.size()) < 12; ++i) lines.push_back(md[i]);
    }
  }
  while (lines.size() < 12) lines.push_back(text(""));
  Element win = borderStyled(cfg_.annual_theme.log_entry_preview_border, vbox(std::move(lines)));
  win = flex_shrink(win);
  if (!focused) win = dim(win);
  return win;
}

Element App::render_annual() {
  bool main_focused = (modal_ == Modal::None);
  std::string title = "Today is: " + pad2(today_.day) + ". " + pad2(today_.month) + ". " + std::to_string(today_.year) +
                      ". " + today_event_string() + " | There are " + std::to_string(logs_.size()) +
                      " log entries for year " + std::to_string(year_) + ".";
  Element title_el = hcenter(underlined(bold(text(title))));

  Element sections = window(text("Sections"), sections_menu_->Render() | vscroll_indicator | frame,
                            cfg_.annual_theme.sections_menu_border);
  sections = sections | size(WIDTH, EQUAL, 25) | size(HEIGHT, EQUAL, 20);
  sections = flex_shrink(sections);
  if (!(main_focused && annual_focus_ == 0)) sections = dim(sections);
  Element tags = window(text("Tags"), tags_menu_->Render() | vscroll_indicator | frame, cfg_.annual_theme.tags_menu_border);
  tags = tags | size(WIDTH, EQUAL, 25) | size(HEIGHT, EQUAL, 20);
  tags = flex_shrink(tags);
  if (!(main_focused && annual_focus_ == 1)) tags = dim(tags);

  Element left = vbox({hbox({sections, tags}), render_events_window()});
  left = flex_shrink(left);
  Element cal = render_calendar(main_focused && annual_focus_ == 2);
  Element row = hbox({left, cal, text(" ")});
  Element preview = render_preview(main_focused && annual_focus_ == 3);
  Element help = dim(text("hjkl/arrow keys - navigation | d - delete log | s - see scratchpads | tab - move focus between menus and calendar"));
  Element content = vbox({title_el, yflex_shrink(hcenter(row)), preview, yflex_shrink(hcenter(help))});
  return center(content);
