Element App::render_scratchpad() {
  bool main_focused = (modal_ == Modal::None);
  Element title = hcenter(bold(text("Scratchpad Manager")));
  Element menu_win = window(text("Scratchpads"), hbox({scratch_menu_->Render()}), cfg_.scratchpad_theme.menu_border);
  menu_win = menu_win | size(WIDTH, GREATER_THAN, 40) | size(HEIGHT, EQUAL, 24);
  if (!main_focused) menu_win = dim(menu_win);
  Elements lines;
  if (scratch_selected_ == 0 || scratch_selected_ - 1 >= static_cast<int>(scratchpads_.size())) {
    lines.push_back(bold(hcenter(underlined(text("Select a scratchpad")))));
    lines.push_back(text("No scratchpad selected"));
  } else {
    const auto& sp = scratchpads_[scratch_selected_ - 1];
    lines.push_back(bold(hcenter(underlined(text(sp.name)))));
    std::string content = repo_.read_file(sp.path);
    for (auto& e : render_markdown(content, cfg_.scratchpad_theme.preview_markdown)) {
      if (lines.size() >= 22) break;
      lines.push_back(e);
    }
  }
  Element preview = borderStyled(cfg_.scratchpad_theme.preview_border, vbox(std::move(lines)));
  preview = preview | size(WIDTH, EQUAL, term_w_ * 3 / 4);
  preview = xflex_shrink(preview);
  preview = dim(preview);
  Element content = vbox({title, separator(), hbox({menu_win, preview}), hcenter(text("Press F1 for help."))});
  return vbox({filler(), yflex_grow(hcenter(content)), filler()});
