Element App::render_modal() {
  switch (modal_) {
    case Modal::Password:
    case Modal::ScratchName:
    case Modal::ScratchRename: {
      std::string title = modal_ == Modal::Password ? "Enter password for log files:" : modal_title_;
      Element body = vbox({separator(), hcenter(vbox({input_->Render(), submit_button_->Render()}))});
      return window(text(title), body);
    }
    case Modal::DeleteLog:
    case Modal::ScratchDelete: {
      std::string title = modal_ == Modal::DeleteLog ? "Are you sure you want to delete a log file?"
                                                     : "Are you sure you want to delete the scratchpad \"" + delete_target_ + "\"?";
      Element body = vbox({separator(), hcenter(hbox({yes_button_->Render(), no_button_->Render()}))});
      return window(text(title), body);
    }
    case Modal::Help: {
      Elements lines;
      MarkdownTheme theme;
      std::string help = kHelpText;
      // split keeping the trailing empty line
      std::vector<std::string> raw;
      std::string cur;
      for (char c : help) {
        if (c == '\n') { raw.push_back(cur); cur.clear(); }
        else cur += c;
      }
      std::string joined;
      for (auto& l : raw) joined += l + "\n";
      auto md = render_markdown(joined, theme);
      for (auto& e : md) lines.push_back(e);
      if (!raw.empty() && raw.back().empty()) lines.push_back(text(""));
      lines.push_back(separator());
      lines.push_back(hcenter(close_button_->Render()));
      return border(vbox(std::move(lines)));
    }
    case Modal::GitError: {
      Element body = vbox({separator(), hcenter(ok_button_->Render())});
      return window(text(git_error_), body);
    }
    default:
      return text("");
  }
}

Element App::render() {
  Element main = view_ == View::Annual ? render_annual() : render_scratchpad();
  if (modal_ == Modal::None) return main;
  Element bg = std::make_shared<ModalBackground>(main);
  return dbox({bg, center(clear_under(render_modal()))});
}

// ------------------------------------------------------------------ events

void App::set_year(int y) {
  year_ = y;
  selected_.year = y;
  int dim = Date::days_in_month(y, selected_.month);
  if (selected_.day > dim) selected_.day = dim;
  preview_scroll_ = 0;
  load_year();
}

void App::move_selection(int delta_days, int month_dir) {
  int dim = Date::days_in_month(selected_.year, selected_.month);
  int nd = selected_.day + delta_days;
  if (nd >= 1 && nd <= dim) {
    selected_.day = nd;
  } else {
    int nm = selected_.month + month_dir;
    if (nm < 1 || nm > 12) return;
    remembered_day_[selected_.month] = selected_.day;
    selected_.month = nm;
    int rd = remembered_day_[nm];
    if (rd < 1) rd = 1;
    rd = std::min(rd, Date::days_in_month(selected_.year, nm));
    selected_.day = rd;
  }
  remembered_day_[selected_.month] = selected_.day;
  preview_scroll_ = 0;
}

bool App::on_calendar_event(const Event& e) {
  if (e == events::ArrowLeft || e.is_char("h")) { move_selection(-1, -1); return true; }
  if (e == events::ArrowRight || e.is_char("l")) { move_selection(1, 1); return true; }
  if (e == events::ArrowUp || e.is_char("k")) { move_selection(-7, -1); return true; }
  if (e == events::ArrowDown || e.is_char("j")) { move_selection(7, 1); return true; }
  if (e == events::Return) { open_log_editor(selected_); return true; }
  return false;
}

bool App::on_preview_event(const Event& e) {
  auto it = logs_.find(selected_);
  int n = it == logs_.end() ? 0 : static_cast<int>(split_lines(it->second.content).size());
  if (e == events::ArrowDown || e.is_char("j")) { preview_scroll_ = std::clamp(preview_scroll_ + 1, 0, std::max(0, n - 1)); return true; }
  if (e == events::ArrowUp || e.is_char("k")) { preview_scroll_ = std::clamp(preview_scroll_ - 1, 0, std::max(0, n - 1)); return true; }
  return false;
}

bool App::on_annual_event(const Event& e) {
  if (e == events::Tab) { annual_focus_ = (annual_focus_ + 1) % 4; return true; }
  if (e == events::TabReverse) { annual_focus_ = (annual_focus_ + 3) % 4; return true; }
  if (view_container_->OnEvent(e)) return true;
  if (e.is_char("d")) {
    if (logs_.count(selected_)) show_modal(Modal::DeleteLog);
    return true;
  }
  if (e.is_char("s")) { view_ = View::Scratchpad; reload_scratchpads(); return true; }
  if (e.is_char("+")) { set_year(year_ + 1); return true; }
  if (e.is_char("-")) { set_year(year_ - 1); return true; }
  if (e.is_char("q") || e == events::Escape) { quit_ = true; return true; }
  if (e == events::F1) { show_modal(Modal::Help); return true; }
  return false;
}

bool App::on_scratchpad_event(const Event& e) {
  if (view_container_->OnEvent(e)) return true;
  if (e.is_char("s")) { view_ = View::Annual; return true; }
  if (e.is_char("q") || e == events::Escape) { quit_ = true; return true; }
  if (e == events::F1) { show_modal(Modal::Help); return true; }
  if (e.is_char("d")) {
    if (scratch_selected_ > 0 && scratch_selected_ - 1 < static_cast<int>(scratchpads_.size())) {
      delete_target_ = scratchpads_[scratch_selected_ - 1].name;
      show_modal(Modal::ScratchDelete);
    }
    return true;
  }
  if (e.is_char("r")) {
    if (scratch_selected_ > 0 && scratch_selected_ - 1 < static_cast<int>(scratchpads_.size())) {
      rename_target_ = scratchpads_[scratch_selected_ - 1].name;
      input_text_.clear();
      input_->cursor_position = 0;
      modal_title_ = "Enter the new name for the scratchpad \"" + rename_target_ + "\":";
      show_modal(Modal::ScratchRename);
    }
    return true;
  }
  return false;
}

bool App::on_event(const Event& e) {
  if (e == events::CtrlC) { quit_ = true; return true; }
  if (modal_ != Modal::None) {
    return modal_container_->OnEvent(e);
  }
  if (view_ == View::Annual) return on_annual_event(e);
  return on_scratchpad_event(e);
}

// ------------------------------------------------------------------ actions

void App::submit_password() {
  std::string pw = input_text_;
  LogRepository test(cfg_.log_dir_path, cfg_.log_filename_format, pw);
  std::string marker = test.read_file(test.marker_path());
  if (marker != "encryption-marker:") {
    error_message_ = "Invalid password provided!";
    exit_code_ = 1;
    quit_ = true;
    return;
  }
  cfg_.password = pw;
  repo_ = LogRepository(cfg_.log_dir_path, cfg_.log_filename_format, pw);
  close_modal();
  loaded_ = true;
  load_year();
}

static std::string ensure_md(const std::string& name) {
  if (name.size() >= 3 && name.substr(name.size() - 3) == ".md") return name;
  return name + ".md";
}

void App::submit_scratch_name() {
  std::string name = input_text_;
  if (modal_title_ == "Scratchpad name cannot be empty.") {
    close_modal();
    input_text_.clear();
    return;
  }
  if (name.empty()) {
    modal_title_ = "Scratchpad name cannot be empty.";
    view_ = View::Annual;
    return;
  }
  if (modal_ == Modal::ScratchRename) {
    std::error_code ec;
    fs::rename(repo_.scratchpad_dir() + "/" + rename_target_, repo_.scratchpad_dir() + "/" + ensure_md(name), ec);
    close_modal();
    scratch_selected_ = 0;
    scratch_menu_->focused_entry = 0;
    reload_scratchpads();
    return;
  }
  close_modal();
  std::string path = repo_.scratchpad_dir() + "/" + ensure_md(name);
  open_scratchpad_editor(path);
}

void App::delete_selected_log() {
  repo_.remove(selected_);
  preview_scroll_ = 0;
  load_year();
}

void App::run_editor_on(const std::string& path) {
  const char* editor = std::getenv("EDITOR");
  if (!editor || !*editor) return;
  term_.Uninstall();
  std::string cmd = std::string(editor) + " \"" + path + "\"";
  int r = std::system(cmd.c_str());
  (void)r;
  term_.Install();
}

void App::open_log_editor(const Date& d) {
  std::string path = repo_.path_for(d);
  if (!repo_.encrypted()) {
    std::error_code ec;
    fs::create_directories(fs::path(path).parent_path(), ec);
    run_editor_on(path);
    if (fs::is_regular_file(path, ec) && fs::file_size(path, ec) == 0) fs::remove(path, ec);
  } else {
    std::random_device rd;
    std::string tmp = "/tmp/caps-log-edit-" + std::to_string(rd() % 1000000) + ".md";
    auto existing = repo_.read(d);
    if (existing) {
      std::ofstream out(tmp, std::ios::binary);
      out << *existing;
    }
    run_editor_on(tmp);
    std::error_code ec;
    if (fs::is_regular_file(tmp, ec)) {
      std::ifstream in(tmp, std::ios::binary);
      std::stringstream ss;
      ss << in.rdbuf();
      std::string content = ss.str();
      if (content.empty()) repo_.remove(d);
      else repo_.write(d, content);
      fs::remove(tmp, ec);
    } else {
      repo_.remove(d);
    }
  }
  preview_scroll_ = 0;
  load_year();
}

void App::open_scratchpad_editor(const std::string& path) {
  std::error_code ec;
  fs::create_directories(fs::path(path).parent_path(), ec);
  if (!repo_.encrypted()) {
    run_editor_on(path);
  } else {
    std::random_device rd;
    std::string tmp = "/tmp/caps-log-edit-" + std::to_string(rd() % 1000000) + ".md";
    if (fs::is_regular_file(path, ec)) {
      std::ofstream out(tmp, std::ios::binary);
      out << repo_.read_file(path);
    }
    run_editor_on(tmp);
    if (fs::is_regular_file(tmp, ec)) {
      std::ifstream in(tmp, std::ios::binary);
      std::stringstream ss;
      ss << in.rdbuf();
      repo_.write_file(path, ss.str());
      fs::remove(tmp, ec);
    }
  }
  scratch_selected_ = 0;
  scratch_menu_->focused_entry = 0;
  reload_scratchpads();
}

// ------------------------------------------------------------------ main loop

int App::run() {
  build_components();
  for (int i = 0; i < 13; ++i) remembered_day_[i] = 1;
  remembered_day_[selected_.month] = selected_.day;
  if (prompt_password_) {
    modal_ = Modal::Password;
    input_text_.clear();
  } else {
    loaded_ = true;
    load_year();
  }
  reload_scratchpads();

  term_.Install();
  while (!quit_) {
    Terminal::Size(&term_w_, &term_h_);
    Screen screen(term_w_, term_h_);
    Element doc = render();
    Render(screen, doc);
    term_.Draw(screen);
    Event ev;
    if (!term_.NextEvent(&ev)) break;
    if (ev.type == Event::Resize) continue;
    on_event(ev);
  }
  term_.Uninstall();
  if (!error_message_.empty()) {
    std::cerr << "Captain's log encountered an error: \n " << error_message_ << std::endl;
  }
  return exit_code_;
}

}  // namespace

int run_app(const RunOptions& options) {
  App app(options);
  return app.run();
}

