namespace fs = std::filesystem;

namespace {

struct CliError : std::runtime_error {
  using std::runtime_error::runtime_error;
};

struct OptionSpec {
  std::string long_name;
  char short_name;
  bool takes_arg;
};

const std::vector<OptionSpec> kOptions = {
    {"help", 'h', false},        {"config", 'c', true},       {"log-dir-path", 0, true},
    {"log-name-format", 0, true}, {"sunday-start", 0, false}, {"first-line-section", 0, false},
    {"password", 0, true},       {"encrypt", 0, false},       {"decrypt", 0, false},
};

struct ParsedArgs {
  std::map<std::string, std::string> values;  // long name -> value ("" for flags)
  bool has(const std::string& k) const { return values.count(k) > 0; }
};

const OptionSpec* FindLong(const std::string& name) {
  const OptionSpec* found = nullptr;
  for (const auto& o : kOptions) {
    if (o.long_name == name) return &o;
    if (o.long_name.rfind(name, 0) == 0) {
      if (found) throw CliError("option '--" + name + "' is ambiguous");
      found = &o;
    }
  }
  return found;
}

void SetValue(ParsedArgs& out, const OptionSpec& spec, const std::string& value) {
  if (out.has(spec.long_name)) throw CliError("option '--" + spec.long_name + "' cannot be specified more than once");
  out.values[spec.long_name] = value;
}

ParsedArgs ParseArgs(int argc, char** argv) {
  ParsedArgs out;
  for (int i = 1; i < argc; ++i) {
    std::string arg = argv[i];
    if (arg.rfind("--", 0) == 0 && arg.size() > 2) {
      std::string body = arg.substr(2);
      std::string name = body, value;
      bool has_value = false;
      size_t eq = body.find('=');
      if (eq != std::string::npos) {
        name = body.substr(0, eq);
        value = body.substr(eq + 1);
        has_value = true;
      }
      const OptionSpec* spec = FindLong(name);
      if (!spec) throw CliError("unrecognised option '" + arg + "'");
      if (spec->takes_arg) {
        if (!has_value) {
          if (i + 1 >= argc) throw CliError("the required argument for option '--" + spec->long_name + "' is missing");
          value = argv[++i];
        }
        SetValue(out, *spec, value);
      } else {
        if (has_value) throw CliError("option '--" + spec->long_name + "' does not take any arguments");
        SetValue(out, *spec, "");
      }
    } else if (arg.size() >= 2 && arg[0] == '-' && arg != "-") {
      char c = arg[1];
      const OptionSpec* spec = nullptr;
      for (const auto& o : kOptions)
        if (o.short_name == c) spec = &o;
      if (!spec) throw CliError("unrecognised option '" + arg + "'");
      if (spec->takes_arg) {
        std::string value;
        if (arg.size() > 2) value = arg.substr(2);
        else {
          if (i + 1 >= argc) throw CliError("the required argument for option '--" + spec->long_name + "' is missing");
          value = argv[++i];
        }
        SetValue(out, *spec, value);
      } else {
        if (arg.size() > 2) throw CliError("unrecognised option '" + arg + "'");
        SetValue(out, *spec, "");
      }
    } else {
      // positional arguments are ignored
    }
  }
  return out;
}

void PrintHelp() {
  std::cout << "Captain's Log (caps-log)! A CLI journalig tool.\n"
               "Version: commit-e3efeaa30714750f300e0d885d80a6c0fc3ff0b2\n"
               "Allowed options:\n"
               "  -h [ --help ]         show this message\n"
               "  -c [ --config ] arg   override the default config file path \n"
               "                        (" << app::default_config_path() << ")\n"
               "  --log-dir-path arg    path where log files are stored\n"
               "  --log-name-format arg format in which log entry markdown files are saved\n"
               "  --sunday-start        have the calendar display sunday as first day of the \n"
               "                        week\n"
               "  --first-line-section  override the default behaviour of ignoring sections \n"
               "                        (lines starting with `#`) in the first line of a log \n"
               "                        entry file\n"
               "  --password arg        password for encrypted log repositories or to be used \n"
               "                        with --encrypt/--decrypt\n"
               "  --encrypt             apply encryption to all logs in log dir path (needs \n"
               "                        --password)\n"
               "  --decrypt             apply decryption to all logs in log dir path (needs \n"
               "                        --password)\n";
}

std::string ReadFileRaw(const std::string& path) {
  std::ifstream in(path, std::ios::binary);
  std::stringstream ss;
  ss << in.rdbuf();
  return ss.str();
}

void WriteFileRaw(const std::string& path, const std::string& data) {
  std::ofstream out(path, std::ios::binary | std::ios::trunc);
  out << data;
}

void ApplyCrypto(const app::Config& cfg, bool encrypt) {
  if (cfg.password.empty()) {
    throw std::runtime_error(encrypt ? "Password must be provided when encrypting logs!"
                                     : "Password must be provided when decrypting logs!");
  }
  std::cout << "Applying crypto..." << std::endl;
  app::LogRepository repo(cfg.log_dir_path, cfg.log_filename_format, cfg.password);
  bool marker = fs::exists(repo.marker_path());
  if (encrypt == marker) throw std::runtime_error("Already applied");
  std::vector<std::string> files = repo.crypto_files();
  for (const auto& f : files) {
    std::string data = ReadFileRaw(f);
    WriteFileRaw(f, encrypt ? crypto::encrypt(data, cfg.password) : crypto::decrypt(data, cfg.password));
  }
  if (encrypt) {
    WriteFileRaw(repo.marker_path(), crypto::encrypt("encryption-marker:", cfg.password));
  } else {
    std::error_code ec;
    fs::remove(repo.marker_path(), ec);
  }
}

bool IsParentPath(const std::string& parent, const std::string& child) {
  std::string p = parent, c = child;
  while (p.size() > 1 && p.back() == '/') p.pop_back();
  while (c.size() > 1 && c.back() == '/') c.pop_back();
  if (c == p) return true;
  return c.rfind(p + "/", 0) == 0;
}

void ValidateGit(const app::Config& cfg) {
  const auto& g = cfg.git;
  if (!g.enabled) return;
  if (g.ssh_key_path.empty()) throw std::runtime_error("SSH key path can not be empty!");
  if (g.ssh_pub_key_path.empty()) throw std::runtime_error("SSH public key path can not be empty!");
  if (g.repo_root.empty()) throw std::runtime_error("Git repository root can not be empty!");
  if (!IsParentPath(g.repo_root, cfg.log_dir_path))
    throw std::runtime_error("Error! Git repo root (" + g.repo_root + ") is not parent of log dir (" + cfg.log_dir_path + ")!");
  if (!fs::exists(g.ssh_key_path)) throw std::runtime_error("SSH key does not exist: " + g.ssh_key_path);
  if (!fs::exists(g.ssh_pub_key_path)) throw std::runtime_error("SSH public key does not exist: " + g.ssh_pub_key_path);
  std::string root = g.repo_root;
  while (root.size() > 1 && root.back() == '/') root.pop_back();
  if (!fs::is_directory(root + "/.git"))
    throw std::runtime_error("Git error @/workspace/source/utils/git_repo.cpp:95\n\tcould not find repository from '" + g.repo_root + "'");
}

