int main(int argc, char** argv) {
  try {
    ParsedArgs args = ParseArgs(argc, argv);
    if (args.has("help")) {
      PrintHelp();
      return 0;
    }
    std::string config_path = args.has("config") ? args.values["config"] : app::default_config_path();
    app::Config cfg = app::load_config(config_path);
    if (args.has("log-dir-path")) cfg.log_dir_path = args.values["log-dir-path"];
    if (args.has("log-name-format")) cfg.log_filename_format = args.values["log-name-format"];
    if (args.has("sunday-start")) cfg.sunday_start = true;
    if (args.has("first-line-section")) cfg.first_line_section = true;
    if (args.has("password")) cfg.password = args.values["password"];
    while (cfg.log_dir_path.size() > 1 && cfg.log_dir_path.back() == '/') cfg.log_dir_path.pop_back();

    if (args.has("encrypt")) { ApplyCrypto(cfg, true); return 0; }
    if (args.has("decrypt")) { ApplyCrypto(cfg, false); return 0; }

    ValidateGit(cfg);

    app::RunOptions opts;
    opts.config = cfg;
    {
      std::error_code ec;
      fs::create_directories(cfg.log_dir_path, ec);
      fs::create_directories(cfg.log_dir_path + "/scratchpads", ec);
    }
    app::LogRepository repo(cfg.log_dir_path, cfg.log_filename_format, cfg.password);
    if (repo.encrypted()) {
      if (cfg.password.empty()) {
        opts.prompt_password = true;
      } else {
        std::string marker = repo.read_file(repo.marker_path());
        if (marker != "encryption-marker:") throw std::runtime_error("Invalid password provided!");
      }
    } else if (!cfg.password.empty()) {
      throw std::runtime_error("Password provided for a non encrypted repository!");
    }
    return app::run_app(opts);
  } catch (const std::exception& e) {
    std::cerr << "Captain's log encountered an error: \n " << e.what() << std::endl;
    return 1;
  }
}
