void App::request_quit() {
  if (cfg_.git.enabled) {
    // The original tool shows a loading window while committing/pushing to the remote.
    git_quitting_ = true;
    return;
  }
  quit_ = true;
}

static bool git_remote_exists(const std::string& repo_root, const std::string& remote) {
  std::string root = repo_root;
  while (root.size() > 1 && root.back() == '/') root.pop_back();
  std::ifstream in(root + "/.git/config");
  std::string line;
  std::string needle = "[remote \\"" + remote + "\\"]";
  while (std::getline(in, line)) {
    size_t a = line.find_first_not_of(" \\t");
    if (a == std::string::npos) continue;
    std::string t = line.substr(a);
    while (!t.empty() && std::isspace(static_cast<unsigned char>(t.back()))) t.pop_back();
    if (t == needle) return true;
  }
  return false;
}

void App::init_git() {
  if (!cfg_.git.enabled) return;
  if (!git_remote_exists(cfg_.git.repo_root, cfg_.git.remote_name)) {
    git_error_ = "Error pulling from remote:Git error @/workspace/source/utils/git_repo.cpp:213remote '" +
